/* ---- FIREBASE HELPERS (via SDK autenticado — nunca mais fetch cru) ---- */
async function fbList(col){
  const snap=await db.collection(col).get();
  return snap.docs.map(d=>({...d.data(),_docName:d.ref.path}));
}
async function fbCreate(col,id,data){
  await db.collection(col).doc(id).set(data);
}
async function fbUpdate(col,id,data){
  await db.collection(col).doc(id).set(data,{merge:true});
}
async function proximoId(prefixo,lista,col_config,campo){
  if(G.mk.modoDemo||G.rel.modoDemo){
    const max=lista.reduce((m,x)=>{const n=parseInt((x.id||`${prefixo}-000`).split('-')[1]||0);return n>m?n:m;},0);
    return`${prefixo}-${String(max+1).padStart(3,'0')}`;
  }
  const[colConfig,docConfig]=col_config.split('/');
  try{
    const ref=db.collection(colConfig).doc(docConfig);
    const snap=await ref.get();
    const seq=((snap.exists&&snap.data()[campo])||0)+1;
    await ref.set({[campo]:seq},{merge:true});
    return`${prefixo}-${String(seq).padStart(3,'0')}`;
  }catch{await fbCreate(col_config.split('/')[0],col_config.split('/')[1],{[campo]:1});return`${prefixo}-001`;}
}

/* ---- UTILS ---- */
function hoje(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;}
function isoParaBR(iso){if(!iso)return'';const[a,m,d]=iso.split('-');return`${d}/${m}/${a}`;}
function brParaISO(br){if(!br)return'';const[d,m,a]=br.split('/');return`${a}-${m}-${d}`;}
// Quem realmente vendeu, pra relatorios por vendedor. "captador" e' quem esta
// com o lead ATUALMENTE atribuido - se o lead foi vendido sem passar por
// "Transferir" antes (comum quando outro vendedor so assume e fecha),
// captador continua com o nome antigo mesmo a venda sendo de outra pessoa.
// O historico da propria acao de "Vendido" registra quem realmente clicou
// nela (campo "by"), que e' a fonte confiavel - so cai pra captador/by do
// lead se por algum motivo essa entrada nao existir (achado a pedido da
// Aline, 02/09/2026: venda de Carteira do Maicon aparecia como do Janderson).
function quemVendeu(l){
  const entrada=[...(l.historico||[])].reverse().find(h=>/vendido/i.test(h.acao||''));
  return (entrada&&entrada.by)||l.captador||l.by||'?';
}
function diasDesdeCompra(dtISO){if(!dtISO)return 0;return Math.floor((new Date()-new Date(dtISO+'T12:00:00'))/(864e5));}
function labelDias(d){if(d<30)return`${d}d`;if(d<365)return`${Math.floor(d/30)}m`;const a=Math.floor(d/365),m=Math.floor((d%365)/30);return m>0?`${a}a ${m}m`:`${a}a`;}
function aniversarioMes(dtNasc){if(!dtNasc)return false;return parseInt(dtNasc.split('-')[1])===new Date().getMonth()+1;}
function mascaraTel(el){let v=el.value.replace(/\D/g,'');el.value=(v.length<=10?v.replace(/(\d{2})(\d{4})(\d+)/,'($1) $2-$3'):v.replace(/(\d{2})(\d{5})(\d+)/,'($1) $2-$3')).substring(0,15);}
function fecharModal(id){document.getElementById(id).classList.add('hidden');}
function fecharDetail(){document.getElementById('detail-ov').classList.add('hidden');document.getElementById('detail-pnl').classList.add('hidden');G.mk.detailId=null;G.rel.detailId=null;}
function toast(msg,tipo='green',ms=3000){
  const el=document.getElementById('toast');el.textContent=msg;
  el.style.background=tipo==='red'?'#e8431e':tipo==='gold'?'#b8860b':'#1a6b3c';
  el.classList.add('show');setTimeout(()=>el.classList.remove('show'),ms);
}

/* ---- AUTH ---- */
async function fazerLogin(){
  const e=document.getElementById('login-email').value.trim().toLowerCase();
  const s=document.getElementById('login-senha').value;
  const erroEl=document.getElementById('login-error');
  const btn=document.getElementById('btn-entrar');
  erroEl.style.display='none';erroEl.style.color='var(--red)';erroEl.style.background='var(--redl)';
  if(!e||!s)return;
  btn.disabled=true;const txtOriginal=btn.textContent;btn.textContent='Entrando...';
  try{
    await fbAuth.signInWithEmailAndPassword(e,s);
  }catch(err){
    erroEl.textContent='E-mail ou senha incorretos.';erroEl.style.display='block';
    btn.disabled=false;btn.textContent=txtOriginal;
    return;
  }
  const u=USUARIOS.find(x=>x.e.toLowerCase()===e);
  if(!u){
    // Login no Firebase deu certo, mas essa pessoa nao esta cadastrada como
    // perfil/permissao do CRM (ex: conta que so existe no sistema irmao).
    await fbAuth.signOut();
    erroEl.textContent='Esse login não tem acesso a este CRM.';erroEl.style.display='block';
    btn.disabled=false;btn.textContent=txtOriginal;
    return;
  }
  entrarNaApp(u);
  btn.disabled=false;btn.textContent=txtOriginal;
}
// Passo comum depois de confirmar quem e a pessoa (login por senha OU
// auto-login quando o sistema principal ja tem sessao no mesmo Firebase
// Auth) - preenche a tela e entra no CRM.
function entrarNaApp(u){
  G.user=u;
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('app-screen').classList.remove('hidden');
  document.getElementById('sb-av').textContent=u.n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
  document.getElementById('sb-name').textContent=u.n;
  document.getElementById('sb-role').textContent=({master:'Master',manager:'Gestão',seller:'Vendedor',coordenadora:'Coordenadora',dev:'Desenvolvedor'}[u.r]||u.r);
  document.querySelectorAll('.ni-sistema-principal').forEach(el=>el.style.display=(u.r==='dev'?'none':''));
  document.getElementById('ni-integracoes').style.display=(u.r==='master'?'':'none');
  popularSelects();
  // Mostrar/ocultar tabs de navegação conforme perfil
  ['ni-geral','ni-rel','ni-ws','ni-an','ni-ia'].forEach(id=>{
    const mod={'ni-geral':'geral','ni-rel':'relacionamento','ni-ws':'workshop','ni-an':'anuncios','ni-ia':'ia'}[id];
    const el=document.getElementById(id);
    if(el) el.style.display=podeVerModulo(mod)?'':'none';
  });
  trocarModulo('marketing');
}
async function recuperarSenha(){
  const erroEl=document.getElementById('login-error');
  const e=document.getElementById('login-email').value.trim().toLowerCase();
  erroEl.style.display='none';
  if(!e){
    erroEl.style.color='var(--red)';erroEl.style.background='var(--redl)';
    erroEl.textContent='Preencha o e-mail acima antes de clicar em "Esqueci minha senha".';erroEl.style.display='block';
    return;
  }
  try{
    await fbAuth.sendPasswordResetEmail(e);
  }catch(err){}
  // Nao informar se o e-mail existe ou nao (mesma protecao contra enumeracao
  // que o Firebase ja usa) - sempre mostra a mesma mensagem de sucesso.
  erroEl.style.color='var(--green)';erroEl.style.background='var(--greenl)';
  erroEl.textContent='Se esse e-mail tiver acesso ao CRM, enviamos um link pra redefinir a senha. Confira sua caixa de entrada (e o spam).';
  erroEl.style.display='block';
}
async function logout(){
  await fbAuth.signOut().catch(()=>{});
  // Sem isso, o auto-refresh e o cronometro continuavam tentando rodar
  // depois do logout (sem sessao valida pro Firestore), gerando erro de
  // "permission-denied" sem parar sozinho.
  if(G.mk._autoRefreshInterval){clearInterval(G.mk._autoRefreshInterval);G.mk._autoRefreshInterval=null;}
  if(G.mk._timerInterval){clearInterval(G.mk._timerInterval);G.mk._timerInterval=null;}
  G.user=null;G.mk.leads=[];G.rel.clientes=[];
  // Resetar visibilidade das tabs para o próximo login
  ['ni-rel','ni-ws','ni-an','ni-ia'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='';});
  document.getElementById('app-screen').classList.add('hidden');
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('login-error').style.display='none';
  document.getElementById('login-email').value='';document.getElementById('login-senha').value='';
}
function popularSelects(){
  const vendedores=USUARIOS.filter(u=>['seller','manager','master'].includes(u.r));
  // vendedor do lead
  const selCap=document.getElementById('f-captador');
  if(selCap){selCap.innerHTML='<option value="">Automático (rodízio)</option>'+VENDEDORES_ATIVOS.map(v=>`<option value="${v}">${v}</option>`).join('');}
  // responsável no relacionamento
  const selResp=document.getElementById('rc-resp');
  if(selResp){
    selResp.innerHTML='<option value="">Selecione...</option>';
    vendedores.forEach(u=>{const o=document.createElement('option');o.value=u.n;o.textContent=u.n;selResp.appendChild(o);});
  }
  // quando origem=Compra, auto-seleciona Milena
  const selOrigem=document.getElementById('f-origem');
  if(selOrigem) selOrigem.onchange=function(){if(this.value==='Compra'&&selCap&&!selCap.value)selCap.value='Milena';};
}

/* ---- NAVEGAÇÃO ENTRE MÓDULOS ---- */
async function trocarModulo(mod){
  if(!podeVerModulo(mod)){toast('Sem acesso a este módulo','err');return;}
  G.modulo=mod;
  fecharDetail();
  document.getElementById('ni-geral').classList.toggle('on',mod==='geral');
  document.getElementById('ni-mk').classList.toggle('on',mod==='marketing');
  document.getElementById('ni-rel').classList.toggle('on',mod==='relacionamento');
  document.getElementById('ni-ws').classList.toggle('on',mod==='workshop');
  document.getElementById('ni-an').classList.toggle('on',mod==='anuncios');
  document.getElementById('ni-ia').classList.toggle('on',mod==='ia');
  document.getElementById('sb-tag').textContent={geral:'Dashboard Geral',marketing:'CRM',relacionamento:'Relacionamento',workshop:'Workshop',anuncios:'Anúncios',ia:'IA (Eva)'}[mod]||mod;
  if(mod==='marketing'){
    if(!G.mk.leads.length)await initMarketing();
    else renderMarketing();
    iniciarAutoRefreshMk();
  } else if(mod==='geral'){
    pararTimerCRM();pararAutoRefreshMk();await initGeral();
  } else if(mod==='workshop'){
    pararTimerCRM();pararAutoRefreshMk();await initWorkshop();
  } else if(mod==='anuncios'){
    pararTimerCRM();pararAutoRefreshMk();await initAnuncios();
  } else if(mod==='ia'){
    pararTimerCRM();pararAutoRefreshMk();await initIA();
  } else {
    pararAutoRefreshMk();
    if(!G.rel.clientes.length)await initRelacionamento();
    else renderRelacionamento();
  }
}


