/* Planilha nativa do Excel (SpreadsheetML 2003 - .xls), gerada sem
   biblioteca nenhuma: e um XML simples (nao ZIP como o .xlsx real), mas o
   Excel abre e edita normalmente, sem os avisos de formato/separador que um
   .csv costuma dar. "numCols" marca por indice quais colunas sao numero
   (pra alinhar a direita e permitir soma) - todo o resto (inclusive
   telefone/ID, mesmo so com digitos) fica como texto de propósito, senao
   Excel mostra telefone em notacao cientifica ou corta o zero da frente. */
function xlsEsc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function gerarLinhaXLS(valores,numCols,ehCabecalho){
  const cels=valores.map((v,i)=>{
    const numero=!ehCabecalho&&numCols&&numCols.includes(i)&&v!==''&&v!=null&&!isNaN(v);
    const styleAttr=ehCabecalho?' ss:StyleID="Cab"':'';
    return `<Cell${styleAttr}><Data ss:Type="${numero?'Number':'String'}">${xlsEsc(v)}</Data></Cell>`;
  }).join('');
  return `<Row>${cels}</Row>`;
}
function baixarXMLWorkbook(nomeArquivo,nomeAba,linhasXml){
  const xml=`<?xml version="1.0"?>\n<?mso-application progid="Excel.Sheet"?>\n<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Cab"><Font ss:Bold="1"/></Style></Styles><Worksheet ss:Name="${xlsEsc(nomeAba)}"><Table>${linhasXml}</Table></Worksheet></Workbook>`;
  const blob=new Blob([xml],{type:'application/vnd.ms-excel;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download=nomeArquivo;document.body.appendChild(a);a.click();a.remove();
  URL.revokeObjectURL(url);
}
function baixarXLS(nomeArquivo,nomeAba,cabecalho,linhas,numCols){
  const linhasXml=gerarLinhaXLS(cabecalho,numCols,true)+linhas.map(l=>gerarLinhaXLS(l,numCols,false)).join('');
  baixarXMLWorkbook(nomeArquivo,nomeAba,linhasXml);
}
/* Variante pra planilhas "livres" (linhas com larguras diferentes, sem um
   cabecalho fixo unico) - caso do relatorio, que empilha varias mini-tabelas.
   Aqui o numero e detectado por celula (sem risco de telefone, e um relatorio
   só com contagens/percentuais). */
function baixarXLSLivre(nomeArquivo,nomeAba,linhas){
  const linhasXml=linhas.map(l=>gerarLinhaXLS(l,l.map((_,i)=>i),false)).join('');
  baixarXMLWorkbook(nomeArquivo,nomeAba,linhasXml);
}
function exportarLeadsCSV(){
  const leads=mkLeadsFiltrados().sort((a,b)=>(b.id||'').localeCompare(a.id||''));
  if(!leads.length){toast('Nenhum lead pra exportar com esses filtros','gold');return;}
  const linhas=leads.map(l=>{
    const col=COLS_MK.find(c=>c.id===l.st)||COLS_MK[0];
    const resultado=l.st==='vendido'?`Vendido${l.dtVenda?' em '+l.dtVenda:''}`:(l.motivoPerda||'-');
    return[l.id||'',l.dt||'',l.clienteNome||'',l.clienteTel||'',l.veiculo||'',l.origem||'',l.captador||l.by||'',col.label,resultado];
  });
  baixarXLS(`leads_${hoje().replace(/\//g,'-')}.xls`,'Leads',['ID','Data','Cliente','Telefone','Veículo','Origem','Vendedor','Etapa','Motivo/Resultado'],linhas);
  toast(`${leads.length} lead(s) exportado(s)!`);
}

/* 26/08/2026, a pedido da Aline: painel "Hoje" com numeros do dia, ja que
   o filtro de data do Funil/Relatorios confundia (misturava lead recebido
   hoje com lead so ATUALIZADO/transferido hoje). Vendedor ve so os
   proprios numeros; Milena ve so os dela; master/gestao ve o total de
   todo mundo (vendedores + Milena) mais dois indicadores extras
   (leads que chegaram na I.A. hoje e quantos estao em atendimento agora,
   somando todos os vendedores). */
// Data de hoje no horario local (Brasilia), nao em UTC - com toISOString()
// (UTC) o "dia" virava 3h antes da meia-noite local de verdade, fazendo o
// painel "Hoje" mostrar tudo zerado no fim da tarde/noite (bug encontrado
// e corrigido a pedido da Aline, 27/08/2026).
function hojeISOlocal(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
// Primeira resposta HUMANA (nao I.A./Autoconf) registrada no historico do
// lead - o momento em que um vendedor de fato respondeu, nao quando o lead
// chegou nem quando a I.A. encaminhou pra esteira. Os relatorios "Hoje"
// (CRM e Dashboard Geral) contam o lead no dia em que o vendedor respondeu,
// nao no dia em que ele chegou - um lead que chega de noite e so e
// respondido na manha seguinte nao pode aparecer como "recebido" no dia da
// chegada nem ficar de fora do relatorio do vendedor no dia em que ele de
// fato atendeu (a pedido da Aline, 02/09/2026). Enquanto nenhum vendedor
// respondeu ainda, o lead nao conta em nenhum dia.
function primeiraRespostaVendedorISO(l){
  const entrada=(l.historico||[]).find(h=>VENDEDORES_ATIVOS.includes(h.by));
  if(!entrada||!entrada.dt)return null;
  const[d,m,a]=entrada.dt.slice(0,10).split('/');
  return(d&&m&&a)?`${a}-${m}-${d}`:null;
}
const ORIGENS_PULA_IA=['Loja','Carteira de clientes','Passante']; // mesma lista do webhook-autoconf
// 28/08/2026, a pedido da Aline: setas pra ver o painel "Hoje" de ate 7
// dias atras (ontem, anteontem...), sem precisar ir no Funil/Relatorios
// (que misturam lead recebido com lead so atualizado naquele dia).
function statsDoDiaMk(nomes,offset=0){
  const hojeISO=hojeISOlocal(offset);
  const hojeBRstr=hoje(offset);
  const ls=G.mk.leads.filter(l=>nomes.includes(l.captador));
  const recebidosHoje=ls.filter(l=>primeiraRespostaVendedorISO(l)===hojeISO);
  const porCanal=lista=>{const m={};lista.forEach(l=>{m[l.origem||'(sem origem)']=(m[l.origem||'(sem origem)']||0)+1;});return Object.entries(m).sort((a,b)=>b[1]-a[1]);};
  const marketingLeads=recebidosHoje.filter(l=>tipoOrigem(l.origem)==='marketing');
  const outrosLeads=recebidosHoje.filter(l=>tipoOrigem(l.origem)!=='marketing');
  return{
    marketing:marketingLeads.length,
    marketingPorCanal:porCanal(marketingLeads),
    outros:outrosLeads.length,
    outrosPorCanal:porCanal(outrosLeads),
    visitas:ls.filter(l=>l.agendamentoData===hojeISO&&l.agendamentoStatus==='compareceu'&&l.origem!=='Compra').length,
    visitasCompra:ls.filter(l=>l.agendamentoData===hojeISO&&l.agendamentoStatus==='compareceu'&&l.origem==='Compra').length,
    agendamentos:ls.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)===hojeISO&&l.origem!=='Compra').length,
    agendamentosCompra:ls.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)===hojeISO&&l.origem==='Compra').length,
    vendas:ls.filter(l=>l.st==='vendido'&&l.dtVenda===hojeBRstr&&l.origem!=='Compra').length,
    compras:ls.filter(l=>l.st==='vendido'&&l.dtVenda===hojeBRstr&&l.origem==='Compra').length,
  };
}
// Clique nos numeros do painel "Hoje" do CRM pra ver quais leads sao esses
// (a pedido da Aline, 03/09/2026) - reaproveita o mesmo modal "ov-drill" do
// Dashboard Geral. Clicar numa linha abre o lead de verdade.
function mostrarDrilldownMk(titulo,leads){
  document.getElementById('drill-titulo').textContent=`${titulo} (${leads.length})`;
  const corpo=document.getElementById('drill-corpo');
  corpo.innerHTML=leads.length
    ?`<div class="lista-table-wrap"><table class="lista-table"><thead><tr><th>Cliente</th><th>Veículo</th><th>Origem</th><th>Vendedor</th></tr></thead><tbody>${leads.map(l=>`<tr style="cursor:pointer" onclick="fecharModal('ov-drill');abrirDetailLead('${l.id}')" title="Clique pra abrir o lead"><td>${l.clienteNome||'(sem nome)'}</td><td>${l.veiculo||'—'}</td><td>${l.origem||'—'}</td><td>${l.captador||l.by||'—'}</td></tr>`).join('')}</tbody></table></div>`
    :'<div style="color:var(--tx3);font-size:13px;padding:10px 0">Nenhum registro nesse período.</div>';
  document.getElementById('ov-drill').classList.remove('hidden');
}
function abrirDrillMk(tipo,chave,nomesStr,offset){
  const nomes=nomesStr?nomesStr.split('|'):null;
  const hojeISO=hojeISOlocal(offset);
  const hojeBRstr=hoje(offset);
  const base=nomes?G.mk.leads.filter(l=>nomes.includes(l.captador)):G.mk.leads;
  let titulo='',leads=[];
  if(tipo==='canal'){
    titulo=`Leads — ${chave}`;
    leads=base.filter(l=>primeiraRespostaVendedorISO(l)===hojeISO&&l.origem===chave);
  }else if(tipo==='visitas'){
    titulo='Visita';
    leads=base.filter(l=>l.agendamentoData===hojeISO&&l.agendamentoStatus==='compareceu'&&l.origem!=='Compra');
  }else if(tipo==='visitasCompra'){
    titulo='Visita Compra';
    leads=base.filter(l=>l.agendamentoData===hojeISO&&l.agendamentoStatus==='compareceu'&&l.origem==='Compra');
  }else if(tipo==='agendamentos'){
    titulo='Agendamento';
    leads=base.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)===hojeISO&&l.origem!=='Compra');
  }else if(tipo==='agendamentosCompra'){
    titulo='Agendamento Compra';
    leads=base.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)===hojeISO&&l.origem==='Compra');
  }else if(tipo==='vendas'){
    titulo='Vendas';
    leads=base.filter(l=>l.st==='vendido'&&l.dtVenda===hojeBRstr&&l.origem!=='Compra');
  }else if(tipo==='compras'){
    titulo='Compra';
    leads=base.filter(l=>l.st==='vendido'&&l.dtVenda===hojeBRstr&&l.origem==='Compra');
  }else if(tipo==='chegaramIA'){
    titulo='Chegaram na I.A.';
    leads=G.mk.leads.filter(l=>l.dtISO===hojeISO&&l.origem!=='Compra'&&!ORIGENS_PULA_IA.includes(l.origem));
  }else if(tipo==='aindaIA'){
    titulo='Ainda na I.A.';
    leads=G.mk.leads.filter(l=>l.dtISO===hojeISO&&l.origem!=='Compra'&&!ORIGENS_PULA_IA.includes(l.origem)&&l.st==='ia');
  }else if(tipo==='jaSairamIA'){
    titulo='Já saíram da I.A.';
    leads=G.mk.leads.filter(l=>l.dtISO===hojeISO&&l.origem!=='Compra'&&!ORIGENS_PULA_IA.includes(l.origem)&&l.st!=='ia');
  }else if(tipo==='emAtendimento'){
    titulo='Em atendimento agora';
    leads=G.mk.leads.filter(l=>l.st==='atendimento');
  }
  mostrarDrilldownMk(titulo,leads);
}
// Vendas da semana/mes atuais por vendedor - usado no painel "Hoje" do CRM
// (a pedido da Aline, 03/09/2026: vendedor nao tem acesso ao Dashboard Geral,
// entao essa informacao tambem precisa aparecer aqui).
function vendasPorPeriodoMk(nomes,iniISO,fimISO){
  const base=nomes?G.mk.leads.filter(l=>nomes.includes(l.captador)):G.mk.leads;
  const vendidos=base.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO));
  const porVendedor={};
  vendidos.forEach(l=>{const v=quemVendeu(l);porVendedor[v]=(porVendedor[v]||0)+1;});
  return{total:vendidos.length,porVendedor};
}
function abrirDrillMkPeriodo(chave,nomesStr,iniISO,fimISO){
  const nomes=nomesStr?nomesStr.split('|'):null;
  const base=nomes?G.mk.leads.filter(l=>nomes.includes(l.captador)):G.mk.leads;
  const leads=chave
    ?base.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&quemVendeu(l)===chave)
    :base.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO));
  mostrarDrilldownMk(chave?`Vendas — ${chave}`:'Vendas do período',leads);
}
function blocoVendasPeriodoMk(nomesStr){
  const nm=nomesStr||'';
  const nomes=nomesStr?nomesStr.split('|'):null;
  const semana=limitesSemanaAtual(),mes=limitesMesAtual();
  const stSemana=vendasPorPeriodoMk(nomes,semana.ini,semana.fim);
  const stMes=vendasPorPeriodoMk(nomes,mes.ini,mes.fim);
  function bloco(titulo,st,iniISO,fimISO){
    const porVendedor=Object.keys(st.porVendedor).length
      ?Object.entries(st.porVendedor).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div style="display:flex;justify-content:space-between;font-size:11px;color:var(--tx2);cursor:pointer" onclick="abrirDrillMkPeriodo('${k}','${nm}','${iniISO}','${fimISO}')" title="Clique pra ver quem são"><span>${k}</span><strong>${v}</strong></div>`).join('')
      :'<div style="color:var(--tx3);font-size:11px;margin-top:6px">Nenhuma</div>';
    return`<div style="background:var(--greenl);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px">
      <div style="font-size:26px;font-weight:700;color:var(--green);text-align:center;cursor:pointer" onclick="abrirDrillMkPeriodo(null,'${nm}','${iniISO}','${fimISO}')" title="Clique pra ver quem são">${st.total}</div>
      <div style="font-size:11px;color:var(--tx3);text-align:center">${titulo}</div>
      <div style="margin-top:6px;display:flex;flex-direction:column;gap:3px">${porVendedor}</div>
    </div>`;
  }
  return`<div class="d-section" style="margin-top:14px"><div class="d-section-title">Vendas — semana e mês atuais (por vendedor)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;margin-top:8px">
      ${bloco(`Semana atual (${isoParaBR(semana.ini)} a ${isoParaBR(semana.fim)})`,stSemana,semana.ini,semana.fim)}
      ${bloco(`Mês atual (${isoParaBR(mes.ini)} a ${isoParaBR(mes.fim)})`,stMes,mes.ini,mes.fim)}
    </div>
  </div>`;
}
// Contagem das colunas NPS e Indicações (Relacionamento) no dia — usada no painel "Hoje" do CRM
function statsNpsIndDoDia(nomes,offset=0){
  const diaISO=hojeISOlocal(offset);
  const doDia=by=>!nomes||nomes.includes(by);
  return{
    nps:G.rel.nps.filter(n=>n.dt===diaISO&&doDia(n.by)).length,
    indicacoes:G.rel.indicacoes.filter(n=>n.dt===diaISO&&doDia(n.by)).length,
  };
}
function renderDashboardHoje(cnt){
  const wrap=document.createElement('div');wrap.className='rel-wrap';
  function kpiCard(val,label,color,bg,onclick){
    const clic=onclick?`cursor:pointer;`:'';
    const attrs=onclick?` onclick="${onclick}" title="Clique pra ver quem são"`:'';
    return`<div style="background:${bg||'var(--bg2)'};border:1px solid var(--bdr);border-radius:var(--r2);padding:16px;text-align:center;${clic}"${attrs}>
      <div style="font-size:28px;font-weight:700;color:${color}">${val}</div>
      <div style="font-size:11px;color:var(--tx3);margin-top:3px">${label}</div>
    </div>`;
  }
  function listaCanais(porCanal,nomesStr,offset){
    if(!porCanal.length)return'<div style="color:var(--tx3);font-size:11px;margin-top:6px">Nenhum</div>';
    return`<div style="margin-top:6px;display:flex;flex-direction:column;gap:3px">${porCanal.map(([canal,n])=>`<div style="display:flex;justify-content:space-between;font-size:11px;color:var(--tx2);cursor:pointer" onclick="abrirDrillMk('canal','${canal}','${nomesStr||''}',${offset})" title="Clique pra ver quem são"><span>${canal}</span><strong>${n}</strong></div>`).join('')}</div>`;
  }
  function blocoStats(titulo,st,nomesStr,offset){
    const nm=nomesStr||'';
    return`<div class="d-section"><div class="d-section-title">${titulo}</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:8px">
        <div style="background:var(--bluel);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px">
          <div style="font-size:26px;font-weight:700;color:var(--blue);text-align:center">${st.marketing}</div>
          <div style="font-size:11px;color:var(--tx3);text-align:center">Leads · Marketing</div>
          ${listaCanais(st.marketingPorCanal,nm,offset)}
        </div>
        <div style="background:var(--purplel);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px">
          <div style="font-size:26px;font-weight:700;color:var(--purple);text-align:center">${st.outros}</div>
          <div style="font-size:11px;color:var(--tx3);text-align:center">Leads · Outros</div>
          ${listaCanais(st.outrosPorCanal,nm,offset)}
        </div>
        ${kpiCard(st.visitas,'Visita','var(--gold)','var(--goldl)',`abrirDrillMk('visitas',null,'${nm}',${offset})`)}
        ${kpiCard(st.visitasCompra,'Visita Compra','var(--gold)','var(--goldl)',`abrirDrillMk('visitasCompra',null,'${nm}',${offset})`)}
        ${kpiCard(st.agendamentos,'Agendamento','var(--gold)','var(--goldl)',`abrirDrillMk('agendamentos',null,'${nm}',${offset})`)}
        ${kpiCard(st.agendamentosCompra,'Agendamento Compra','var(--gold)','var(--goldl)',`abrirDrillMk('agendamentosCompra',null,'${nm}',${offset})`)}
        ${kpiCard(st.vendas,'Vendas','var(--green)','var(--greenl)',`abrirDrillMk('vendas',null,'${nm}',${offset})`)}
        ${kpiCard(st.compras,'Compra','var(--green)','var(--greenl)',`abrirDrillMk('compras',null,'${nm}',${offset})`)}
      </div>
    </div>`;
  }
  const offset=G.mk.hojeOffset||0;
  const rotuloDia=offset===0?'Hoje':(offset===-1?'Ontem':`${Math.abs(offset)} dias atrás`);
  let html=`<div style="padding:20px;overflow:auto">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px">
      <button class="btn btn-outline btn-sm" ${offset<=-7?'disabled':''} onclick="__G().mk.hojeOffset=(__G().mk.hojeOffset||0)-1;renderMarketing()" title="Dia anterior"><i class="ti ti-chevron-left"></i></button>
      <h2 style="font-size:18px">📅 ${rotuloDia} — ${hoje(offset)}</h2>
      <button class="btn btn-outline btn-sm" ${offset>=0?'disabled':''} onclick="__G().mk.hojeOffset=(__G().mk.hojeOffset||0)+1;renderMarketing()" title="Dia seguinte"><i class="ti ti-chevron-right"></i></button>
      ${offset!==0?'<button class="btn btn-outline btn-sm" onclick="__G().mk.hojeOffset=0;renderMarketing()">Voltar pra hoje</button>':''}
    </div>`;
  if(G.user?.r==='master'){
    const TODOS_VENDEDORES=['Marcela','Rafael','Aline','Milena','Janderson','Maicon','Rubens','Jean'];
    const stTodos=statsDoDiaMk(TODOS_VENDEDORES,offset);
    const diaISO=hojeISOlocal(offset);
    // mesma lista de origens que o webhook-autoconf usa pra pular a I.A.
    // (cadastro manual de vendedor) - o resto passa pela I.A. normalmente.
    const chegaramNoDia=G.mk.leads.filter(l=>l.dtISO===diaISO&&l.origem!=='Compra'&&!ORIGENS_PULA_IA.includes(l.origem));
    const aindaNaIA=chegaramNoDia.filter(l=>l.st==='ia').length;
    const jaSairamDaIA=chegaramNoDia.length-aindaNaIA;
    const emAtendimentoAgora=G.mk.leads.filter(l=>l.st==='atendimento').length;
    const stNpsIndTodos=statsNpsIndDoDia(null,offset);
    html+=`<p style="color:var(--tx3);font-size:12px;margin-bottom:14px">Total de todos os vendedores + Milena</p>`;
    html+=blocoStats('Equipe toda',stTodos,TODOS_VENDEDORES.join('|'),offset);
    html+=`<div class="d-section" style="margin-top:14px"><div class="d-section-title">Dos leads que chegaram ${offset===0?'hoje':'nesse dia'} na I.A.</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:8px">
        ${kpiCard(chegaramNoDia.length,offset===0?'Chegaram na I.A. hoje':'Chegaram na I.A.','var(--purple)','var(--purplel)',`abrirDrillMk('chegaramIA',null,null,${offset})`)}
        ${kpiCard(aindaNaIA,'Ainda na I.A.','var(--purple)','var(--purplel)',`abrirDrillMk('aindaIA',null,null,${offset})`)}
        ${kpiCard(jaSairamDaIA,'Já saíram da I.A.','var(--blue)','var(--bluel)',`abrirDrillMk('jaSairamIA',null,null,${offset})`)}
      </div>
    </div>
    <div class="d-section" style="margin-top:14px"><div class="d-section-title">NPS e Indicações — Relacionamento (${offset===0?'hoje':'nesse dia'})</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:8px">
        ${kpiCard(stNpsIndTodos.nps,'💬 NPS pedidos','#0b7ba8','#e8f8fb')}
        ${kpiCard(stNpsIndTodos.indicacoes,'🎯 Indicações recebidas','#c2185b','#fde8f0')}
      </div>
    </div>
    ${blocoVendasPeriodoMk(TODOS_VENDEDORES.join('|'))}
    ${offset===0?`<div class="d-section" style="margin-top:14px"><div class="d-section-title">Painel operacional (agora, todos os leads em aberto — não só os de hoje)</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:8px">
        ${kpiCard(emAtendimentoAgora,'Em atendimento agora (todos)','var(--blue)','var(--bluel)',"abrirDrillMk('emAtendimento',null,null,0)")}
      </div>
    </div>`:''}`;
  }else{
    const meusNomes=[G.user?.n];
    const st=statsDoDiaMk(meusNomes,offset);
    const stNpsInd=statsNpsIndDoDia(meusNomes,offset);
    html+=blocoStats(`Seus números — ${G.user?.n||''}`,st,meusNomes.join('|'),offset);
    html+=`<div class="d-section" style="margin-top:14px"><div class="d-section-title">NPS e Indicações — Relacionamento (${offset===0?'hoje':'nesse dia'})</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-top:8px">
        ${kpiCard(stNpsInd.nps,'💬 NPS pedidos','#0b7ba8','#e8f8fb')}
        ${kpiCard(stNpsInd.indicacoes,'🎯 Indicações recebidas','#c2185b','#fde8f0')}
      </div>
    </div>
    ${blocoVendasPeriodoMk(meusNomes.join('|'))}`;
  }
  html+='</div>';
  wrap.innerHTML=html;
  cnt.appendChild(wrap);
}
/* ============================================================
   DASHBOARD GERAL — visão consolidada do dia (CRM + Relacionamento)
   ============================================================ */
async function initGeral(){
  document.getElementById('tb').innerHTML='';
  document.getElementById('cnt').innerHTML='<div class="full-load"><i class="ti ti-loader-2"></i> Carregando...</div>';
  if(fbOk()){
    try{
      if(!G.mk.leads.length)G.mk.leads=await fbList('leads');
      if(!G.rel.clientes.length)G.rel.clientes=await fbList('clientes_rel');
      if(!G.rel.nps.length)G.rel.nps=await fbList('nps_rel');
      if(!G.rel.indicacoes.length)G.rel.indicacoes=await fbList('indicacoes_rel');
    }catch(e){console.error(e);toast('Erro ao carregar dados.','red');}
  }
  renderGeral();
}
// Um unico calculo por intervalo [iniISO,fimISO] (inclusive) — o painel do
// dia (setas) e o painel "por filtro" (data inicio/fim) usam a mesma
// funcao, so muda o intervalo passado. dtVenda fica salvo em BR (dd/mm/aaaa),
// entao precisa converter pra ISO antes de comparar como intervalo.
function vendaNoPeriodoISO(l,iniISO,fimISO){const v=brParaISO(l.dtVenda);return!!v&&v>=iniISO&&v<=fimISO;}
function leadRecebidoNoPeriodo(l,iniISO,fimISO){const r=primeiraRespostaVendedorISO(l);return!!r&&r>=iniISO&&r<=fimISO;}
function statsGeralIntervalo(iniISO,fimISO){
  // Mesmo criterio do painel "Hoje" do CRM: conta pela data em que um
  // vendedor de fato respondeu (nao a data de chegada do lead).
  const leadsNoPeriodo=G.mk.leads.filter(l=>leadRecebidoNoPeriodo(l,iniISO,fimISO));
  const clientes=G.rel.clientes;
  const vendaNoPeriodo=l=>vendaNoPeriodoISO(l,iniISO,fimISO);

  // Compra entra somada dentro dos leads de Marketing nesse dashboard
  // (a pedido da Aline, 02/09/2026: "compra é do marketing").
  const leadsPorCanalMkt={};ORIGENS_MK.marketing.forEach(o=>{leadsPorCanalMkt[o]=leadsNoPeriodo.filter(l=>l.origem===o).length;});
  const leadsCompra=leadsNoPeriodo.filter(l=>ORIGENS_MK.compra.includes(l.origem)).length;
  leadsPorCanalMkt['Compra']=leadsCompra;
  const totalLeadsMkt=Object.values(leadsPorCanalMkt).reduce((a,b)=>a+b,0);
  const leadsPassanteLojaEvento=leadsNoPeriodo.filter(l=>['Passante','Loja','Evento Externo'].includes(l.origem)).length;
  const leadsMyBusinessOutra=leadsNoPeriodo.filter(l=>['My Business','Outra'].includes(l.origem)).length;
  const leadsCarteiraProspIndic=leadsNoPeriodo.filter(l=>['Carteira','Prospecção','Indicação'].includes(l.origem)).length;
  const totalLeadsOutros=leadsNoPeriodo.filter(l=>ORIGENS_MK.outros.includes(l.origem)).length;

  const npsInd={
    nps:G.rel.nps.filter(n=>n.dt>=iniISO&&n.dt<=fimISO).length,
    indicacoes:G.rel.indicacoes.filter(n=>n.dt>=iniISO&&n.dt<=fimISO).length,
  };

  const visitas1ano=clientes.filter(c=>c.visita1ano==='realizada'&&c.visita1anoData>=iniISO&&c.visita1anoData<=fimISO).length;
  const visitas2anos=clientes.filter(c=>c.visita2anos==='realizada'&&c.visita2anosData>=iniISO&&c.visita2anosData<=fimISO).length;

  const visitasMkt=G.mk.leads.filter(l=>l.agendamentoData>=iniISO&&l.agendamentoData<=fimISO&&l.agendamentoStatus==='compareceu'&&tipoOrigem(l.origem)==='marketing').length;
  const visitasOutras=G.mk.leads.filter(l=>l.agendamentoData>=iniISO&&l.agendamentoData<=fimISO&&l.agendamentoStatus==='compareceu'&&tipoOrigem(l.origem)==='outros').length;

  const agendamento=G.mk.leads.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)>=iniISO&&l.pendente_at.slice(0,10)<=fimISO&&l.origem!=='Compra').length;
  const agendamentoCompra=G.mk.leads.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)>=iniISO&&l.pendente_at.slice(0,10)<=fimISO&&l.origem==='Compra').length;

  const vendasMktPorCanal={};ORIGENS_MK.marketing.forEach(o=>{const n=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodo(l)&&l.origem===o).length;if(n>0)vendasMktPorCanal[o]=n;});
  const vendasOutrosPorCanal={};ORIGENS_MK.outros.forEach(o=>{const n=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodo(l)&&l.origem===o).length;if(n>0)vendasOutrosPorCanal[o]=n;});
  const vendasCompra=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodo(l)&&l.origem==='Compra').length;
  const vendasPorVendedor={};G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodo(l)).forEach(l=>{const v=quemVendeu(l);vendasPorVendedor[v]=(vendasPorVendedor[v]||0)+1;});
  const totalVendasMkt=Object.values(vendasMktPorCanal).reduce((a,b)=>a+b,0);
  const totalVendasOutros=Object.values(vendasOutrosPorCanal).reduce((a,b)=>a+b,0);
  const totalVendasVendedor=Object.values(vendasPorVendedor).reduce((a,b)=>a+b,0);

  return{leadsPorCanalMkt,totalLeadsMkt,leadsPassanteLojaEvento,leadsMyBusinessOutra,leadsCarteiraProspIndic,totalLeadsOutros,leadsCompra,
    npsInd,visitas1ano,visitas2anos,visitasMkt,visitasOutras,agendamento,agendamentoCompra,
    vendasMktPorCanal,totalVendasMkt,vendasOutrosPorCanal,totalVendasOutros,vendasCompra,vendasPorVendedor,totalVendasVendedor};
}
function statsGeralDoDia(offset=0){
  const diaISO=hojeISOlocal(offset);
  return statsGeralIntervalo(diaISO,diaISO);
}
function trocarViewGeral(v){
  G.geral.view=v;
  if(v==='filtro'&&!G.geral.filtroDataInicio&&!G.geral.filtroDataFim){
    // Primeira vez que abre o filtro: comeca com a semana atual (ultimos 7 dias), pra nao vir em branco
    G.geral.filtroDataInicio=hojeISOlocal(-6);
    G.geral.filtroDataFim=hojeISOlocal(0);
  }
  renderGeral();
}
/* Clique nos numeros do Dashboard Geral pra ver quem esta por tras deles
   (a pedido da Aline, 03/09/2026: "tivemos 2 vendas, quero saber de quem
   foi essa venda, que carro foi vendido"). */
function mostrarDrilldown(titulo,itens,colunas){
  document.getElementById('drill-titulo').textContent=`${titulo} (${itens.length})`;
  const corpo=document.getElementById('drill-corpo');
  corpo.innerHTML=itens.length
    ?`<div class="lista-table-wrap"><table class="lista-table"><thead><tr>${colunas.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${itens.map(l=>`<tr>${l.map(v=>`<td>${v||'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
    :'<div style="color:var(--tx3);font-size:13px;padding:10px 0">Nenhum registro nesse período.</div>';
  document.getElementById('ov-drill').classList.remove('hidden');
}
const GRUPOS_OUTROS_REL={passante:['Passante','Loja','Evento Externo'],mybusiness:['My Business','Outra'],carteira:['Carteira','Prospecção','Indicação']};
function abrirDrill(tipo,chave,iniISO,fimISO){
  const fmtV=l=>l.valor?`R$ ${l.valor}`:'';
  const vendedorLead=l=>l.captador||l.by||'';
  let titulo='',itens=[],colunas=[];
  if(tipo==='leadsCanal'){
    titulo=`Leads — ${chave}`;
    itens=G.mk.leads.filter(l=>leadRecebidoNoPeriodo(l,iniISO,fimISO)&&l.origem===chave)
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Vendedor'];
  }else if(tipo==='leadsGrupoOutros'){
    const origens=GRUPOS_OUTROS_REL[chave]||[];
    titulo=`Leads — ${origens.join(' + ')}`;
    itens=G.mk.leads.filter(l=>leadRecebidoNoPeriodo(l,iniISO,fimISO)&&origens.includes(l.origem))
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor'];
  }else if(tipo==='leadsTotalMkt'){
    titulo='Leads — Total Marketing (inclui Compra)';
    itens=G.mk.leads.filter(l=>leadRecebidoNoPeriodo(l,iniISO,fimISO)&&(tipoOrigem(l.origem)==='marketing'||tipoOrigem(l.origem)==='compra'))
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor'];
  }else if(tipo==='leadsTotalOutros'){
    titulo='Leads — Total Outros Canais';
    itens=G.mk.leads.filter(l=>leadRecebidoNoPeriodo(l,iniISO,fimISO)&&tipoOrigem(l.origem)==='outros')
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor'];
  }else if(tipo==='vendasCanal'){
    titulo=`Vendas — ${chave}`;
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&l.origem===chave)
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',quemVendeu(l),fmtV(l)]);
    colunas=['Cliente','Veículo','Vendedor','Valor'];
  }else if(tipo==='vendasTotalMkt'){
    titulo='Vendas — Total Marketing';
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&tipoOrigem(l.origem)==='marketing')
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',quemVendeu(l),fmtV(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor','Valor'];
  }else if(tipo==='vendasTotalOutros'){
    titulo='Vendas — Total Outros Canais';
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&tipoOrigem(l.origem)==='outros')
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',quemVendeu(l),fmtV(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor','Valor'];
  }else if(tipo==='vendasVendedor'){
    titulo=`Vendas — ${chave}`;
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&quemVendeu(l)===chave)
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',fmtV(l)]);
    colunas=['Cliente','Veículo','Origem','Valor'];
  }else if(tipo==='vendasTotal'){
    titulo='Vendas — Total do período';
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO))
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',quemVendeu(l),fmtV(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor','Valor'];
  }else if(tipo==='vendasCompra'){
    titulo='Vendas — Compra';
    itens=G.mk.leads.filter(l=>l.st==='vendido'&&vendaNoPeriodoISO(l,iniISO,fimISO)&&l.origem==='Compra')
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',quemVendeu(l),fmtV(l)]);
    colunas=['Cliente','Veículo','Vendedor','Valor'];
  }else if(tipo==='nps'){
    titulo='NPS pedidos';
    itens=G.rel.nps.filter(n=>n.dt>=iniISO&&n.dt<=fimISO).map(n=>[n.nome||'(sem nome)',n.tel||'',isoParaBR(n.dt)]);
    colunas=['Nome','Telefone','Data'];
  }else if(tipo==='indicacoes'){
    titulo='Indicações recebidas';
    itens=G.rel.indicacoes.filter(n=>n.dt>=iniISO&&n.dt<=fimISO)
      .map(n=>[n.nomeIndicado||'(sem nome)',n.telIndicado||'',n.indicadoPor||'',n.tag==='compareceu'?'✅ Compareceu':(n.tag==='nao_compareceu'?'❌ Não compareceu':'—'),isoParaBR(n.dt)]);
    colunas=['Indicado','Telefone','Indicado por','Status','Data'];
  }else if(tipo==='visitas1ano'||tipo==='visitas2anos'){
    const campo=tipo==='visitas1ano'?'visita1ano':'visita2anos',campoData=campo+'Data';
    titulo=tipo==='visitas1ano'?'Visitas 1 ano':'Visitas 2 anos';
    itens=G.rel.clientes.filter(c=>c[campo]==='realizada'&&c[campoData]>=iniISO&&c[campoData]<=fimISO)
      .map(c=>[c.clienteNome||'(sem nome)',c.veiculo||'',isoParaBR(c[campoData])]);
    colunas=['Cliente','Veículo','Data da visita'];
  }else if(tipo==='visitasMkt'||tipo==='visitasOutras'){
    const tipoAlvo=tipo==='visitasMkt'?'marketing':'outros';
    titulo=tipo==='visitasMkt'?'Visitas marketing':'Visitas outras';
    itens=G.mk.leads.filter(l=>l.agendamentoData>=iniISO&&l.agendamentoData<=fimISO&&l.agendamentoStatus==='compareceu'&&tipoOrigem(l.origem)===tipoAlvo)
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor'];
  }else if(tipo==='agendamento'||tipo==='agendamentoCompra'){
    titulo=tipo==='agendamento'?'Agendamento':'Agendamento compra';
    itens=G.mk.leads.filter(l=>l.pendente_at&&l.pendente_at.slice(0,10)>=iniISO&&l.pendente_at.slice(0,10)<=fimISO&&(tipo==='agendamento'?l.origem!=='Compra':l.origem==='Compra'))
      .map(l=>[l.clienteNome||'(sem nome)',l.veiculo||'',l.origem||'',vendedorLead(l)]);
    colunas=['Cliente','Veículo','Origem','Vendedor'];
  }
  mostrarDrilldown(titulo,itens,colunas);
}
function geralRpRow(label,val,forte,onclick){
  const clic=onclick?` style="cursor:pointer" onclick="${onclick}" title="Clique pra ver quem são"`:'';
  return `<div class="rp-row${forte?' rp-total':''}"${clic}><span>${label}</span><strong>${val}</strong></div>`;
}
function geralIndBox(titulo,icone1,label1,val1,cor1,onclick1,icone2,label2,val2,cor2,onclick2){
  const c1=onclick1?` style="cursor:pointer" onclick="${onclick1}" title="Clique pra ver quem são"`:'';
  const c2=onclick2?` style="cursor:pointer" onclick="${onclick2}" title="Clique pra ver quem são"`:'';
  return `<div class="geral-ind-box">
    <div class="hd">${titulo}</div>
    <div class="stat"${c1}><div class="n" style="color:${cor1}">${val1}</div><div class="l">${icone1} ${label1}</div></div>
    <div class="stat"${c2}><div class="n" style="color:${cor2}">${val2}</div><div class="l">${icone2} ${label2}</div></div>
  </div>`;
}
function geralListaCanalCard(titulo,emoji,itens,total,corTotal,cols2,onclickChave,onclickTotal){
  const rows=Object.entries(itens).map(([k,v])=>geralRpRow(k,v,false,onclickChave?onclickChave(k):null));
  const linhas=rows.length?(cols2?`<div class="geral-cols2">${rows.join('')}</div>`:rows.join('')):'<div style="color:var(--tx3);font-size:11px">Nenhum</div>';
  const clicTotal=onclickTotal?` style="cursor:pointer" onclick="${onclickTotal}" title="Clique pra ver quem são"`:'';
  return `<div class="rp-section">
    <div class="rp-sec-title">${emoji} ${titulo}</div>
    ${linhas}
    <div class="rp-row rp-total"${clicTotal}><span>Total</span><strong style="color:${corTotal||'inherit'}">${total}</strong></div>
  </div>`;
}
// Semana (segunda a domingo) e mês (dia 1 ao último dia) de HOJE — sempre a
// atual, independente de qual dia/período esta selecionado no dashboard
// (a pedido da Aline, 03/09/2026).
function limitesSemanaAtual(){
  const hoje=new Date();const dow=(hoje.getDay()+6)%7;
  return{ini:hojeISOlocal(-dow),fim:hojeISOlocal(6-dow)};
}
function limitesMesAtual(){
  const hoje=new Date();
  const iniD=new Date(hoje.getFullYear(),hoje.getMonth(),1);
  const fimD=new Date(hoje.getFullYear(),hoje.getMonth()+1,0);
  const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  return{ini:iso(iniD),fim:iso(fimD)};
}
function geralBlocoResumoVendas(){
  const semana=limitesSemanaAtual(),mes=limitesMesAtual();
  const stSemana=statsGeralIntervalo(semana.ini,semana.fim);
  const stMes=statsGeralIntervalo(mes.ini,mes.fim);
  const totalSemana=stSemana.totalVendasMkt+stSemana.totalVendasOutros+stSemana.vendasCompra;
  const totalMes=stMes.totalVendasMkt+stMes.totalVendasOutros+stMes.vendasCompra;
  function bloco(tituloResumo,st,total,iniISO,fimISO){
    const p=`'${iniISO}','${fimISO}'`;
    const porVendedor=Object.keys(st.vendasPorVendedor).length
      ?Object.entries(st.vendasPorVendedor).sort((a,b)=>b[1]-a[1]).map(([k,v])=>geralRpRow(k,v,false,`abrirDrill('vendasVendedor','${k}',${p})`)).join('')
      :'<div style="color:var(--tx3);font-size:11px">Nenhuma</div>';
    return`<div class="rp-section">
      <div class="rp-sec-title">💰 ${tituloResumo}</div>
      <div class="rp-row rp-total" style="cursor:pointer" onclick="abrirDrill('vendasTotal',null,${p})" title="Clique pra ver quem são"><span>Total</span><strong style="color:#1a6b3c">${total}</strong></div>
      ${porVendedor}
    </div>`;
  }
  return`
    <div class="rel-section-title" style="margin:14px 0 6px"><i class="ti ti-calendar-stats"></i> Vendas — semana e mês atuais (por vendedor)</div>
    <div class="rp-grid" style="margin-bottom:14px">
      ${bloco(`Semana atual (${isoParaBR(semana.ini)} a ${isoParaBR(semana.fim)})`,stSemana,totalSemana,semana.ini,semana.fim)}
      ${bloco(`Mês atual (${isoParaBR(mes.ini)} a ${isoParaBR(mes.fim)})`,stMes,totalMes,mes.ini,mes.fim)}
    </div>`;
}
