  const qualifOutros=all.filter(l=>l.st==='qualificado'&&!ORIGENS_MK.marketing.includes(l.origem));
  const emConversa=all.filter(l=>l.st==='em_conversa');
  const aguardando=all.filter(l=>l.st==='aguardando');
