/* RODÍZIO DE VENDEDORES — lead sem vendedor definido cai automaticamente no próximo da fila.
   Para incluir mais alguém no rodízio, basta acrescentar o nome no array abaixo.
   O contador é incrementado via fieldTransform atômico do Firestore (increment), em vez de
   ler-e-gravar em duas chamadas separadas — assim duas criações de lead ao mesmo tempo nunca
   leem o mesmo número e caem no mesmo vendedor. */
const RODIZIO_VENDEDORES=['Janderson','Maicon','Victor'];
async function proximoVendedorRodizio(){
  if(!RODIZIO_VENDEDORES.length)return'';
  if(G.mk.modoDemo){
    const i=(G.mk._rodizioIdx||0)%RODIZIO_VENDEDORES.length;
    G.mk._rodizioIdx=i+1;
    return RODIZIO_VENDEDORES[i];
  }
  try{
    const escolhido=await db.runTransaction(async tx=>{
      const ref=db.collection('leads_config').doc('rodizio');
      const snap=await tx.get(ref);
      const dados=snap.exists?snap.data():{};
      // So entra no sorteio quem estiver marcado ativo na fila (painel
      // Integracoes) - por padrao todo mundo do RODIZIO_VENDEDORES esta
      // ativo, a nao ser que tenha sido desligado explicitamente.
      const ativos=RODIZIO_VENDEDORES.filter(n=>dados.ativos?.[n]!==false);
      const lista=ativos.length?ativos:RODIZIO_VENDEDORES;
      const atual=dados.idx||0;
      tx.set(ref,{idx:atual+1},{merge:true});
      return lista[atual%lista.length];
    });
    return escolhido;
  }catch{
    await fbCreate('leads_config','rodizio',{idx:1});
    return RODIZIO_VENDEDORES[0];
  }
}
async function toggleVendedorEsteira(nome){
  const ref=db.collection('leads_config').doc('rodizio');
  const snap=await ref.get();
  const dados=snap.exists?snap.data():{};
  const ativos=dados.ativos||{};
  const estavaAtivo=ativos[nome]!==false;
  ativos[nome]=!estavaAtivo;
  await ref.set({ativos},{merge:true});
  abrirModalIntegracoes();
}
async function abrirModalIntegracoes(){
  document.getElementById('ov-integracoes').classList.remove('hidden');
  const body=document.getElementById('integracoes-body');
  body.innerHTML='Carregando...';
  const [rodizioSnap,errosSnap]=await Promise.all([
    db.collection('leads_config').doc('rodizio').get(),
    db.collection('erros_webhook').get(),
  ]);
  const ativos=(rodizioSnap.exists&&rodizioSnap.data().ativos)||{};
  const agora=Date.now();
  const erros48h=errosSnap.docs.map(d=>d.data()).filter(e=>e.criadoEm&&(agora-new Date(e.criadoEm).getTime())<48*3600*1000).sort((a,b)=>b.criadoEm.localeCompare(a.criadoEm));
  const leadsAutoconf=G.mk.leads.filter(l=>l.autoconfLeadId).sort((a,b)=>(b._criadoEm||'').localeCompare(a._criadoEm||''));
  const ultimoLead=leadsAutoconf[0];
  const horasSemLead=ultimoLead&&ultimoLead._criadoEm?Math.floor((agora-new Date(ultimoLead._criadoEm).getTime())/3600000):null;
  const semLeadHaMuito=horasSemLead!==null&&horasSemLead>24;
  const tudoOk=!erros48h.length&&!semLeadHaMuito;
  body.innerHTML=`
    <div class="d-section">
      <div class="d-section-title">Status Autoconf</div>
      <div style="background:${tudoOk?'var(--greenl)':'var(--redl)'};border:1px solid var(--bdr);border-radius:var(--r2);padding:14px;margin-top:8px">
        <div style="font-weight:700;color:${tudoOk?'var(--green)':'var(--red)'};font-size:14px">${tudoOk?'✅ Tudo certo':'⚠️ Precisa de atenção'}</div>
        <div style="font-size:12px;color:var(--tx2);margin-top:6px">
          ${ultimoLead?`Último lead recebido há ${horasSemLead<1?'menos de 1 hora':horasSemLead+'h'}${semLeadHaMuito?' <strong style="color:var(--red)">(mais de 24h sem receber nada — verifique se a integração caiu)</strong>':''}`:'Nenhum lead do Autoconf encontrado ainda'}
        </div>
        <div style="font-size:12px;color:var(--tx2);margin-top:4px">${erros48h.length?`<strong style="color:var(--red)">${erros48h.length} erro(s) registrado(s)</strong> nas últimas 48h`:'Nenhum erro registrado nas últimas 48h'}</div>
      </div>
      ${erros48h.length?`<div style="margin-top:8px;max-height:140px;overflow:auto">${erros48h.slice(0,10).map(e=>`<div style="font-size:11px;color:var(--tx3);padding:4px 0;border-bottom:1px solid var(--bdr)">${new Date(e.criadoEm).toLocaleString('pt-BR')} — ${(e.erro||'').slice(0,120)}</div>`).join('')}</div>`:''}
    </div>
    <div class="d-section" style="margin-top:16px">
      <div class="d-section-title">Fila de atendimento (rodízio)</div>
      <p style="font-size:12px;color:var(--tx3);margin-top:4px">Desative quem não estiver atendendo hoje — ele para de receber lead novo automaticamente até você reativar.</p>
      <div style="display:flex;flex-direction:column;gap:8px;margin-top:10px">
        ${RODIZIO_VENDEDORES.map(nome=>{
          const ativo=ativos[nome]!==false;
          return`<div style="display:flex;align-items:center;justify-content:space-between;background:var(--bg3);border-radius:var(--r);padding:10px 14px">
            <span style="font-weight:600;font-size:13px">${nome}</span>
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:12px;color:${ativo?'var(--green)':'var(--tx3)'}">
              ${ativo?'Na fila':'Fora da fila'}
              <input type="checkbox" ${ativo?'checked':''} onchange="toggleVendedorEsteira('${nome}')">
            </label>
          </div>`;
        }).join('')}
      </div>
    </div>`;
}
async function salvarLead(){
  const nome=document.getElementById('f-nome').value.trim(),tel=document.getElementById('f-tel').value.trim(),origem=document.getElementById('f-origem').value;
  if(!nome){toast('Informe o nome','red');return;}if(!tel){toast('Informe o telefone','red');return;}if(!origem){toast('Selecione a origem','red');return;}
  if(!G.mk.editandoId){
    const telDigits=tel.replace(/\D/g,'');
    const dup=G.mk.leads.find(l=>l.clienteTel&&l.clienteTel.replace(/\D/g,'')===telDigits&&!['vendido','perdido'].includes(l.st));
    if(dup){
      const colDup=COLS_MK.find(c=>c.id===dup.st);
      document.getElementById('lead-duplicado-msg').innerHTML=`Já existe um lead em aberto com esse telefone: <strong>${dup.id} — ${dup.clienteNome||'(sem nome)'}</strong>, na etapa <strong>${colDup?.label||dup.st}</strong>${dup.captador?` com <strong>${dup.captador}</strong>`:''}.<br><br>Avise o Master pra confirmar quem deve continuar esse atendimento, em vez de cadastrar de novo.`;
      document.getElementById('ov-lead-duplicado').classList.remove('hidden');
      setTimeout(()=>document.getElementById('btn-duplicado-entendi').focus(),50);
      return;
    }
  }
  const btn=document.getElementById('btn-salvar-lead');btn.disabled=true;document.getElementById('btn-salvar-lead-txt').innerHTML='<span class="spin"></span>';
  let captador=document.getElementById('f-captador').value;if(origem==='Compra'&&!captador)captador='Milena';
  if(!captador&&!G.mk.editandoId)captador=await proximoVendedorRodizio();
  const dtISO=document.getElementById('f-data-contato').value||new Date().toISOString().split('T')[0];
  const stEscolhido=document.getElementById('f-etapa').value||'aguardando';
  const agora=new Date().toISOString();
  const leadExistente=G.mk.editandoId?G.mk.leads.find(l=>l.id===G.mk.editandoId):null;
  const data={clienteNome:nome,clienteTel:tel,clienteEmail:document.getElementById('f-email').value.trim(),origem,captador:captador||G.user?.n||'',by:G.user?.n||'',uid:G.user?.id||'',veiculo:document.getElementById('f-veiculo').value.trim(),valor:document.getElementById('f-valor').value.trim(),st:stEscolhido,dtISO,dt:isoParaBR(dtISO),obs:document.getElementById('f-obs').value.trim()};
  // Cronometro das colunas com timer (Atendimento/Agendamento): sem isso, um
  // lead criado ou movido manualmente pra essas etapas nunca teria a contagem
  // em vermelho, so os que chegavam automaticamente pelo Autoconf/Eva.
  if(stEscolhido==='atendimento'&&!(leadExistente&&leadExistente.atendimento_at))data.atendimento_at=agora;
  if(stEscolhido==='agendamento'&&!(leadExistente&&leadExistente.pendente_at))data.pendente_at=agora;
  if(stEscolhido==='encantamento'&&!(leadExistente&&leadExistente.encantamento_at))data.encantamento_at=agora;
  if(stEscolhido==='negociacao'&&!(leadExistente&&leadExistente.negociacao_at))data.negociacao_at=agora;
  // Sem isso, marcar "Venda" direto pelo dropdown de Etapa (em vez do botao
  // "✅ Vendido") nunca gravava a data da venda - achado ao investigar por
  // que o painel "Hoje" nao batia com vendas que a Aline sabia que tinham
  // acontecido (27/08/2026).
  if(stEscolhido==='vendido'&&!(leadExistente&&leadExistente.dtVenda))data.dtVenda=hoje();
  try{
    if(G.mk.editandoId){Object.assign(G.mk.leads.find(l=>l.id===G.mk.editandoId),data);await salvarCamposMk(G.mk.editandoId,data);toast('Lead atualizado!');}
    else{const id=await proximoId('LEAD',G.mk.leads,'leads_config/mk','leadSeq');const lead={id,convertido:false,dtVenda:'',motivoPerda:'',historico:[],_criadoEm:agora,...data};G.mk.leads.push(lead);if(!G.mk.modoDemo)await fbCreate('leads',id,lead);await regHistMk(lead,'Lead criado',`Origem: ${data.origem}`,data.captador||G.user?.n||'');toast(`Lead ${id} criado!`);}
    fecharModal('ov-lead');renderMarketing();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
  finally{btn.disabled=false;document.getElementById('btn-salvar-lead-txt').textContent=G.mk.editandoId?'Salvar Alterações':'Salvar Lead';}
}
