/* ============================================================
   IMPORTAÇÃO — planilha de clientes direto pra uma coluna do
   Relacionamento (Nome/Cliente, Data de compra, Data de nascimento,
   Carro, Telefone, Vendedor)
   ============================================================ */
function normTxt(s){return(s||'').toString().normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();}
const IMPORT_ALIASES={
  nome:['nome','cliente'],
  dtCompra:['data de compra','data da compra','compra','dtcompra','data compra'],
  dtNascimento:['data de nascimento','data nascimento','nascimento','dtnascimento'],
  carro:['carro','veiculo','veiculo comprado'],
  telefone:['telefone','tel','fone','celular','whatsapp'],
  vendedor:['vendedor'],
};
function isoFromExcelSerial(n){
  const ms=Date.UTC(1899,11,30)+Math.round(n*86400000);
  const d=new Date(ms);
  return`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
}
function paraISOImport(v){
  if(v===undefined||v===null||v==='')return'';
  if(v instanceof Date)return`${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;
  if(typeof v==='number')return isoFromExcelSerial(v);
  const s=v.toString().trim();if(!s)return'';
  let m=s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if(m)return`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(m)return`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  return'';
}
function linhaImportParaCampos(row){
  const campos={nome:'',dtCompra:'',dtNascimento:'',carro:'',telefone:'',vendedor:''};
  Object.entries(row).forEach(([chave,valor])=>{
    const n=normTxt(chave);
    for(const campo in IMPORT_ALIASES){
      if(IMPORT_ALIASES[campo].includes(n)){
        campos[campo]=(campo==='dtCompra'||campo==='dtNascimento')?paraISOImport(valor):(valor||'').toString().trim();
        break;
      }
    }
  });
  return campos;
}
function processarArquivoImportacao(input){
  const file=input.files&&input.files[0];if(!file)return;
  const reader=new FileReader();
  reader.onload=e=>{
    try{
      const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
      const sheet=wb.Sheets[wb.SheetNames[0]];
      const linhasBrutas=XLSX.utils.sheet_to_json(sheet,{defval:''});
      G.rel.importLinhas=linhasBrutas.map(linhaImportParaCampos).filter(l=>Object.values(l).some(v=>v));
      if(!G.rel.importLinhas.length)toast('Nenhuma linha encontrada na planilha','red');
    }catch(err){console.error(err);toast('Erro ao ler a planilha — confira o formato (.xlsx, .xls ou .csv)','red');G.rel.importLinhas=null;}
    renderRelacionamento();
  };
  reader.readAsArrayBuffer(file);
}
async function confirmarImportacaoRel(){
  const colId=G.rel.importColuna;const linhas=G.rel.importLinhas;
  if(!colId){toast('Selecione a coluna de destino','red');return;}
  if(!linhas||!linhas.length){toast('Escolha um arquivo primeiro','red');return;}
  const col=COLS_REL.find(x=>x.id===colId);if(!col)return;
  const validas=linhas.filter(l=>l.nome);
  if(!validas.length){toast('Nenhuma linha com nome pra importar','red');return;}
  G.rel.importando=true;renderRelacionamento();
  let criados=0;
  for(const l of validas){
    try{
      const id=await proximoId('REL',G.rel.clientes,'rel_config/seq','relSeq');
      const camposEtapa=col.baseId?{st:col.baseId,[col.campo]:col.valorAtivo?'realizada':''}:{st:col.id};
      const c={
        id,clienteNome:l.nome,clienteTel:l.telefone||'',clienteEmail:'',dtNascimento:l.dtNascimento||'',
        responsavel:'Milena',by:G.user?.n||'',uid:G.user?.id||'',veiculo:l.carro||'',dtCompra:l.dtCompra||'',
        valor:'',vendedor:l.vendedor||'',obs:'',historico:[],...camposEtapa,
      };
      c.historico=[{dt:hoje(),icone:'blue',acao:'📋 Cliente importado',obs:`Importado para ${col.label}${l.vendedor?' — Vendedor: '+l.vendedor:''}`,by:G.user?.n||''}];
      G.rel.clientes.push(c);
      if(!G.rel.modoDemo)await fbCreate('clientes_rel',id,c);
      criados++;
    }catch(err){console.error('Erro ao importar linha',l,err);}
  }
  G.rel.importando=false;G.rel.importLinhas=null;
  toast(`${criados} cliente(s) importado(s) para ${col.label}!`);
  renderRelacionamento();
}
