async function moverClienteParaCol(c,novaColId){
  const newCol=COLS_REL.find(x=>x.id===novaColId);if(!newCol)return;
  const oldCol=colAtualRel(c);if(oldCol.id===newCol.id)return;
  const campos={};
  if(newCol.baseId){
    c.st=newCol.baseId;campos.st=newCol.baseId;
    c[newCol.campo]=newCol.valorAtivo?'realizada':'';campos[newCol.campo]=c[newCol.campo];
    c[newCol.campo+'Data']=newCol.valorAtivo?new Date().toISOString().split('T')[0]:'';campos[newCol.campo+'Data']=c[newCol.campo+'Data'];
  }
  else{c.st=newCol.id;campos.st=newCol.id;}
  await salvarCamposRel(c.id,campos);
  await regHistRel(c,`${newCol.emoji} Avançou para ${newCol.label}`,`Anterior: ${oldCol.label}`,G.user?.n||'',newCol.emoji);
  toast(`${c.clienteNome} → ${newCol.emoji} ${newCol.label}`);
}
async function dropCliente(novaCol){
  if(!G.rel.dragId)return;const c=G.rel.clientes.find(x=>x.id===G.rel.dragId);if(!c)return;
  await moverClienteParaCol(c,novaCol);renderRelacionamento();
}
function renderListaRel(cnt){
  const wrap=document.createElement('div');wrap.className='lista-wrap';
  const clis=relClisFiltrados().sort((a,b)=>(b.id||'').localeCompare(a.id||''));
  const tw=document.createElement('div');tw.className='lista-table-wrap';
  if(!clis.length){tw.innerHTML='<div class="lista-empty"><i class="ti ti-heart-handshake"></i><p>Nenhum cliente encontrado</p></div>';}
  else{
    const t=document.createElement('table');t.className='lista-table';
    t.innerHTML='<thead><tr><th>ID</th><th>Cliente</th><th>Telefone</th><th>Veículo</th><th>Compra</th><th>Tempo</th><th>Etapa</th><th>Responsável</th></tr></thead>';
    const tb2=document.createElement('tbody');
    clis.forEach(c=>{
      const col=colAtualRel(c);const dias=diasDesdeCompra(c.dtCompra);
      const tr=document.createElement('tr');
      tr.innerHTML=`<td><strong style="font-size:11px;color:var(--tx2)">${c.id}</strong></td><td><strong>${c.clienteNome||'-'}</strong></td><td style="font-size:12px">${c.clienteTel||'-'}</td><td style="font-size:12px;max-width:150px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${c.veiculo||'-'}</td><td style="font-size:12px;color:var(--tx3);white-space:nowrap">${isoParaBR(c.dtCompra)||'-'}</td><td><span class="badge" style="background:${col.bg};color:${col.cor}">${labelDias(dias)}</span></td><td><span style="font-size:16px">${col.emoji}</span> <span style="font-size:12px;font-weight:600;color:${col.cor}">${col.label}</span></td><td style="font-size:12px">${c.responsavel||c.by||'-'}</td>`;
      tr.onclick=()=>abrirDetailCliente(c.id);tb2.appendChild(tr);
    });
    t.appendChild(tb2);tw.appendChild(t);
  }
  wrap.appendChild(tw);cnt.appendChild(wrap);
}

/* DASHBOARD RELACIONAMENTO */
function renderDashboardRel(cnt){
  cnt.style.cssText='flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:20px';
  const clis=relClisFiltrados();
  const total=clis.length;

  // Por etapa
  const porEtapa={};COLS_REL.forEach(c=>{porEtapa[c.id]=0;});
  clis.forEach(c=>{const colId=colAtualRel(c).id;if(porEtapa[colId]!==undefined)porEtapa[colId]++;});

  // Métricas de acompanhamento por etapa
  const d7total=clis.filter(c=>c.st==='d7').length;
  const d7env=clis.filter(c=>c.d7Enviado).length;
  const d7rec=clis.filter(c=>c.d7Recebido).length;
  const d90total=clis.filter(c=>c.st==='d90').length;
  const d90env=clis.filter(c=>c.d90Enviado).length;

  // Visitas
  const v1real=clis.filter(c=>c.visita1ano==='realizada').length;
  const v1nao=clis.filter(c=>c.visita1ano==='nao_realizada').length;
  const v1total=clis.filter(c=>c.st==='d1ano').length;
  const v2real=clis.filter(c=>c.visita2anos==='realizada').length;
  const v2nao=clis.filter(c=>c.visita2anos==='nao_realizada').length;
  const v2total=clis.filter(c=>c.st==='d2anos').length;

  // Aniversários próximos (30 dias)
  const hoje=new Date();
  const anivProximos=clis.filter(c=>{
    if(!c.dtNascimento)return false;
    const [,am,ad]=c.dtNascimento.split('-');
    const aniv=new Date(hoje.getFullYear(),+am-1,+ad);
    if(aniv<hoje)aniv.setFullYear(hoje.getFullYear()+1);
    return(aniv-hoje)/(1000*60*60*24)<=30;
  }).map(c=>{
    const [,am,ad]=c.dtNascimento.split('-');
    const aniv=new Date(hoje.getFullYear(),+am-1,+ad);
    if(aniv<hoje)aniv.setFullYear(hoje.getFullYear()+1);
    return{...c,_dias:Math.round((aniv-hoje)/(1000*60*60*24))};
  }).sort((a,b)=>a._dias-b._dias);

  function barFill(n,total,color){
    const pct=total?Math.round(n/total*100):0;
    return `<div style="background:var(--bdr);border-radius:4px;height:8px;margin-top:4px;overflow:hidden"><div style="background:${color};height:100%;border-radius:4px;width:${pct}%;transition:width .3s"></div></div>`;
  }
  function kpiCard(val,label,color,bg){
    return `<div style="background:${bg||'var(--bg2)'};border:1px solid var(--bdr);border-radius:var(--r2);padding:14px;text-align:center">
      <div style="font-size:26px;font-weight:700;color:${color}">${val}</div>
      <div style="font-size:11px;color:var(--tx3);margin-top:3px">${label}</div>
    </div>`;
  }
  function visitaCard(emoji,label,total,real,nao,cor){
    const pend=Math.max(0,total-real-nao);
    return `<div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px">
      <div style="font-size:12px;font-weight:600;margin-bottom:10px">${emoji} ${label}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">
        <span style="font-size:11px;background:#e8f5ee;color:#1a6b3c;padding:2px 8px;border-radius:20px">✅ Realizada: ${real}</span>
        <span style="font-size:11px;background:#fff0ec;color:#e8431e;padding:2px 8px;border-radius:20px">❌ Não veio: ${nao}</span>
        <span style="font-size:11px;background:var(--bg3);color:var(--tx3);padding:2px 8px;border-radius:20px">⏳ Pendente: ${pend}</span>
      </div>
      ${real+nao>0?barFill(real,real+nao,'#1a6b3c'):'<div style="font-size:11px;color:var(--tx3)">Sem registros ainda</div>'}
    </div>`;
  }
  function contarSimNao(campo){return{sim:clis.filter(c=>c[campo]==='sim').length,nao:clis.filter(c=>c[campo]==='nao').length};}
  function simNaoCard(label,sim,nao){
    return `<div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:12px">
      <div style="font-size:11px;font-weight:600;margin-bottom:8px;color:var(--tx2)">${label}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <span style="font-size:11px;background:#e8f5ee;color:#1a6b3c;padding:2px 8px;border-radius:20px">✅ Sim: ${sim}</span>
        <span style="font-size:11px;background:#fff0ec;color:#e8431e;padding:2px 8px;border-radius:20px">❌ Não: ${nao}</span>
      </div>
    </div>`;
  }
  const ind1=contarSimNao('indicacao1ano'),fb1=contarSimNao('feedback1ano');
  const ind2=contarSimNao('indicacao2anos'),fb2=contarSimNao('feedback2anos');
  const indG=contarSimNao('indicacaoGeral'),fbG=contarSimNao('feedbackGeral');
  const recompras=clis.filter(c=>c.recompra==='sim').length;

  // Métricas do mês (Milena)
  function dentroDoMes(dataISO){
    if(!dataISO)return false;
    const d=new Date(dataISO+'T12:00:00'),hj=new Date();
    return d.getMonth()===hj.getMonth()&&d.getFullYear()===hj.getFullYear();
  }
  function contarMes(campo){return clis.filter(c=>c[campo]==='sim'&&dentroDoMes(c[campo+'Data'])).length;}
  const visitas1anoMes=clis.filter(c=>c.visita1ano==='realizada'&&dentroDoMes(c.visita1anoData)).length;
  const vitrificacoesMes=clis.filter(c=>c.visita2anos==='realizada'&&dentroDoMes(c.visita2anosData)).length;
  const indicacoesMes=contarMes('indicacao1ano')+contarMes('indicacao2anos')+contarMes('indicacaoGeral');
  const npsMes=contarMes('feedback1ano')+contarMes('feedback2anos')+contarMes('feedbackGeral');

  // Contagem diária/mensal das colunas NPS e Indicações (Aline)
  function dentroDoDia(dataISO){if(!dataISO)return false;return dataISO===new Date().toISOString().split('T')[0];}
  const npsHoje=G.rel.nps.filter(n=>dentroDoDia(n.dt)).length;
  const npsMesRegistrado=G.rel.nps.filter(n=>dentroDoMes(n.dt)).length;
  const indHoje=G.rel.indicacoes.filter(n=>dentroDoDia(n.dt)).length;
  const indMesRegistrado=G.rel.indicacoes.filter(n=>dentroDoMes(n.dt)).length;
  const indCompareceuMes=G.rel.indicacoes.filter(n=>n.tag==='compareceu'&&dentroDoMes(n.dt)).length;
  const indNaoCompareceuMes=G.rel.indicacoes.filter(n=>n.tag==='nao_compareceu'&&dentroDoMes(n.dt)).length;

  cnt.innerHTML=`
    <!-- KPIs do mês (Milena) -->
    <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px">
      <div style="font-size:13px;font-weight:600;margin-bottom:14px;display:flex;align-items:center;gap:6px">
        <i class="ti ti-calendar-stats" style="color:var(--purple)"></i> Este mês
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">
        ${kpiCard(visitas1anoMes,'🎁 Visitas 1 ano','#6b3db8','#f3e8fb')}
        ${kpiCard(indicacoesMes,'🤝 Indicações','#1a6b3c','#e8f5ee')}
        ${kpiCard(npsMes,'💬 NPS (feedbacks)','#1e4d8c','#e8f0fb')}
        ${kpiCard(vitrificacoesMes,'✨ Vitrificações','#0b7ba8','#e8f8fb')}
      </div>
    </div>

    <!-- Contagem NPS e Indicações — colunas do Jornada (Milena) -->
    <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px">
      <div style="font-size:13px;font-weight:600;margin-bottom:14px;display:flex;align-items:center;gap:6px">
        <i class="ti ti-clipboard-list" style="color:var(--purple)"></i> NPS e Indicações (colunas do Jornada)
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">
        ${kpiCard(npsHoje,'📊 NPS pedidos hoje','#0b7ba8','#e8f8fb')}
        ${kpiCard(npsMesRegistrado,'📊 NPS pedidos no mês','#0b7ba8','#e8f8fb')}
        ${kpiCard(indHoje,'🎯 Indicações hoje','#c2185b','#fde8f0')}
        ${kpiCard(indMesRegistrado,'🎯 Indicações no mês','#c2185b','#fde8f0')}
        ${kpiCard(indCompareceuMes,'✅ Compareceram no mês','#1a6b3c','#e8f5ee')}
        ${kpiCard(indNaoCompareceuMes,'❌ Não compareceram no mês','#e8431e','#fff0ec')}
      </div>
    </div>

    <!-- KPIs totais -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">
      ${kpiCard(total,'Total de Clientes','var(--red)','')}
      ${COLS_REL.filter(c=>!['aniversario','d3anos','d4anos'].includes(c.id)).map(c=>kpiCard(porEtapa[c.id]||0,c.emoji+' '+c.label,c.cor,c.bg)).join('')}
      ${kpiCard(anivProximos.length,'🎂 Aniv. 30 dias','#b8860b','#fff8e1')}
      ${kpiCard(recompras,'🔁 Recompras','var(--purple)','var(--purplel)')}
    </div>

    <!-- Acompanhamento de mensagens -->
    <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px">
      <div style="font-size:13px;font-weight:600;margin-bottom:14px;display:flex;align-items:center;gap:6px">
        <i class="ti ti-chart-bar" style="color:var(--purple)"></i> Acompanhamento de Ações por Etapa
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px">
        <!-- 7 dias -->
        <div>
          <div style="font-size:12px;font-weight:600;color:#1e4d8c;margin-bottom:8px">💬 7 dias (${d7total} clientes)</div>
          <div style="display:flex;justify-content:space-between;font-size:11px"><span>Mensagem enviada</span><span style="font-weight:600">${d7env}/${d7total}</span></div>
          ${barFill(d7env,d7total,'#1e4d8c')}
          <div style="display:flex;justify-content:space-between;font-size:11px;margin-top:6px"><span>Feedback recebido</span><span style="font-weight:600">${d7rec}/${d7total}</span></div>
          ${barFill(d7rec,d7total,'#1a6b3c')}
        </div>
        <!-- 90 dias -->
        <div>
          <div style="font-size:12px;font-weight:600;color:#b8860b;margin-bottom:8px">🔧 90 dias (${d90total} clientes)</div>
          <div style="display:flex;justify-content:space-between;font-size:11px"><span>Aviso de garantia enviado</span><span style="font-weight:600">${d90env}/${d90total}</span></div>
          ${barFill(d90env,d90total,'#b8860b')}
        </div>
      </div>
    </div>

    <!-- Visitas -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px">
      ${visitaCard('🎁','Cesta 1 ano',v1total,v1real,v1nao,'#6b3db8')}
      ${visitaCard('✨','Vitrificação 2 anos',v2total,v2real,v2nao,'#0b7ba8')}
    </div>

    <!-- Indicações e Feedback (KPIs Milena) -->
    <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px">
      <div style="font-size:13px;font-weight:600;margin-bottom:14px;display:flex;align-items:center;gap:6px">
        <i class="ti ti-thumb-up" style="color:var(--purple)"></i> Indicações e Feedback por Marco
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px">
        ${simNaoCard('🤝 Indicação · 1 ano',ind1.sim,ind1.nao)}
        ${simNaoCard('💬 Feedback · 1 ano',fb1.sim,fb1.nao)}
        ${simNaoCard('🤝 Indicação · 2 anos',ind2.sim,ind2.nao)}
        ${simNaoCard('💬 Feedback · 2 anos',fb2.sim,fb2.nao)}
        ${simNaoCard('🤝 Indicação · Geral',indG.sim,indG.nao)}
        ${simNaoCard('💬 Feedback · Geral',fbG.sim,fbG.nao)}
      </div>
    </div>

    <!-- Aniversários próximos -->
    ${anivProximos.length?`
    <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px">
      <div style="font-size:13px;font-weight:600;margin-bottom:12px;display:flex;align-items:center;gap:6px">
        <i class="ti ti-cake" style="color:#b8860b"></i> Aniversários nos próximos 30 dias
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">
        ${anivProximos.map(c=>`
        <div style="background:${c._dias<=7?'#fff8e1':'var(--bg3)'};border:1px solid ${c._dias<=7?'#f0c040':'var(--bdr)'};border-radius:var(--r2);padding:10px 12px;display:flex;gap:10px;align-items:center">
          <div style="font-size:22px">🎂</div>
          <div>
            <div style="font-size:12px;font-weight:500">${c.clienteNome||'—'}</div>
            <div style="font-size:11px;color:var(--tx3)">${c._dias===0?'Hoje!':c._dias===1?'Amanhã':'Em '+c._dias+' dias'}</div>
            <div style="font-size:11px;color:var(--tx3)">${c.responsavel||'—'}</div>
          </div>
        </div>`).join('')}
      </div>
    </div>`:''}
  `;
}

/* CRUD RELACIONAMENTO */
function abrirModalCliente(id=null,etapa=null){
  G.rel.editandoId=id;const c=id?G.rel.clientes.find(x=>x.id===id):null;
  document.getElementById('mod-cliente-titulo').textContent=id?'Editar Cliente':'Novo Cliente';
  document.getElementById('btn-salvar-cli-txt').textContent=id?'Salvar Alterações':'Salvar';
  document.getElementById('rc-nome').value=c?.clienteNome||'';document.getElementById('rc-tel').value=c?.clienteTel||'';
  document.getElementById('rc-email').value=c?.clienteEmail||'';document.getElementById('rc-nasc').value=c?.dtNascimento||'';
  document.getElementById('rc-resp').value=c?.responsavel||c?.by||G.user?.n||'';document.getElementById('rc-veiculo').value=c?.veiculo||'';
  document.getElementById('rc-vendedor').value=c?.vendedor||'';
  document.getElementById('rc-dtcompra').value=c?.dtCompra||new Date().toISOString().split('T')[0];
  document.getElementById('rc-valor').value=c?.valor||'';document.getElementById('rc-etapa').value=c?.st||etapa||'nome';
  document.getElementById('rc-obs').value=c?.obs||'';
  document.getElementById('ov-cliente').classList.remove('hidden');setTimeout(()=>document.getElementById('rc-nome').focus(),50);
}
async function salvarCliente(){
  const nome=document.getElementById('rc-nome').value.trim(),tel=document.getElementById('rc-tel').value.trim(),veiculo=document.getElementById('rc-veiculo').value.trim(),dtCompra=document.getElementById('rc-dtcompra').value;
  if(!nome){toast('Informe o nome','red');return;}if(!tel){toast('Informe o telefone','red');return;}if(!veiculo){toast('Informe o veículo','red');return;}if(!dtCompra){toast('Informe a data da compra','red');return;}
  const btn=document.getElementById('btn-salvar-cli');btn.disabled=true;document.getElementById('btn-salvar-cli-txt').innerHTML='<span class="spin"></span>';
  const data={clienteNome:nome,clienteTel:tel,clienteEmail:document.getElementById('rc-email').value.trim(),dtNascimento:document.getElementById('rc-nasc').value,responsavel:document.getElementById('rc-resp').value||G.user?.n||'',by:G.user?.n||'',uid:G.user?.id||'',veiculo,dtCompra,valor:document.getElementById('rc-valor').value.trim(),st:document.getElementById('rc-etapa').value||'nome',obs:document.getElementById('rc-obs').value.trim(),vendedor:document.getElementById('rc-vendedor').value||''};
  try{
    if(G.rel.editandoId){Object.assign(G.rel.clientes.find(x=>x.id===G.rel.editandoId),data);await salvarCamposRel(G.rel.editandoId,data);toast('Cliente atualizado!');}
    else{const id=await proximoId('REL',G.rel.clientes,'rel_config/seq','relSeq');const c={id,historico:[],...data};G.rel.clientes.push(c);if(!G.rel.modoDemo)await fbCreate('clientes_rel',id,c);await regHistRel(c,'📋 Cliente cadastrado',`Veículo: ${veiculo}`,data.responsavel||G.user?.n||'','📋');toast(`${nome} cadastrado!`);}
    fecharModal('ov-cliente');renderRelacionamento();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
  finally{btn.disabled=false;document.getElementById('btn-salvar-cli-txt').textContent=G.rel.editandoId?'Salvar Alterações':'Salvar';}
}
const VENDEDORES_CARTEIRA=['Rafael','Maicon','Janderson','Victor'];
let _vendedorPopup=null;
function abrirVendedorPopup(id,e){
  e.stopPropagation();
  if(_vendedorPopup){_vendedorPopup.remove();_vendedorPopup=null;}
  const popup=document.createElement('div');
  popup.className='transfer-popup';
  popup.innerHTML=`<div class="tp-title">Vendedor que atendeu</div>${VENDEDORES_CARTEIRA.map(v=>`<button onclick="confirmarVendedorPopup('${id}','${v}')">${v}</button>`).join('')}<button onclick="confirmarVendedorPopup('${id}','')" style="color:var(--tx3)">Limpar</button>`;
  (document.getElementById('rtcar-crm-root')||document.body).appendChild(popup);
  const btn=e.currentTarget;
  const rect=btn.getBoundingClientRect();
  popup.style.top=(rect.bottom+6)+'px';
  popup.style.left=rect.left+'px';
  _vendedorPopup=popup;
  setTimeout(()=>document.addEventListener('click',()=>{popup.remove();_vendedorPopup=null;},{once:true}),50);
}
async function confirmarVendedorPopup(id,vendedor){
  if(_vendedorPopup){_vendedorPopup.remove();_vendedorPopup=null;}
  const c=G.rel.clientes.find(x=>x.id===id);if(!c)return;
  c.vendedor=vendedor;
  await salvarCamposRel(id,{vendedor});
  renderRelacionamento();
  toast(vendedor?`Vendedor: ${vendedor}`:'Vendedor removido');
}
/* CRUD NPS — registro isolado, apenas para contagem (não faz parte da jornada) */
function abrirModalNps(id=null){
  G.rel.editandoNpsId=id;const n=id?G.rel.nps.find(x=>x.id===id):null;
  document.getElementById('mod-nps-titulo').textContent=id?'Editar registro NPS':'Novo registro NPS';
  document.getElementById('rc-nps-nome').value=n?.nome||'';
  document.getElementById('rc-nps-tel').value=n?.tel||'';
  document.getElementById('rc-nps-obs').value=n?.obs||'';
  document.getElementById('btn-salvar-nps-txt').textContent=id?'Salvar Alterações':'Salvar';
  document.getElementById('ov-nps').classList.remove('hidden');setTimeout(()=>document.getElementById('rc-nps-nome').focus(),50);
}
async function salvarNps(){
  const nome=document.getElementById('rc-nps-nome').value.trim();
  if(!nome){toast('Informe o nome','red');return;}
  const btn=document.getElementById('btn-salvar-nps');btn.disabled=true;document.getElementById('btn-salvar-nps-txt').innerHTML='<span class="spin"></span>';
  const data={nome,tel:document.getElementById('rc-nps-tel').value.trim(),obs:document.getElementById('rc-nps-obs').value.trim()};
  try{
    if(G.rel.editandoNpsId){Object.assign(G.rel.nps.find(x=>x.id===G.rel.editandoNpsId),data);if(!G.rel.modoDemo)await fbUpdate('nps_rel',G.rel.editandoNpsId,data);toast('Registro atualizado!');}
    else{const id=await proximoId('NPS',G.rel.nps,'rel_config/seq','npsSeq');const n={id,dt:new Date().toISOString().split('T')[0],by:G.user?.n||'',...data};G.rel.nps.push(n);if(!G.rel.modoDemo)await fbCreate('nps_rel',id,n);toast(`${nome} adicionado ao NPS!`);}
    fecharModal('ov-nps');renderRelacionamento();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
  finally{btn.disabled=false;document.getElementById('btn-salvar-nps-txt').textContent=G.rel.editandoNpsId?'Salvar Alterações':'Salvar';}
}
async function excluirNps(id){
  if(!confirm('Excluir este registro de NPS?'))return;
  G.rel.nps=G.rel.nps.filter(x=>x.id!==id);
  try{if(!G.rel.modoDemo)await db.collection('nps_rel').doc(id).delete();}catch(e){console.error(e);}
  toast('Registro removido');renderRelacionamento();
}
/* CRUD Indicações — registro isolado, apenas controle de comparecimento (não faz parte da jornada) */
function abrirModalIndicacao(id=null){
  G.rel.editandoIndId=id;const n=id?G.rel.indicacoes.find(x=>x.id===id):null;
  document.getElementById('mod-ind-titulo').textContent=id?'Editar indicação':'Nova indicação';
  document.getElementById('ri-nome').value=n?.nomeIndicado||'';
  document.getElementById('ri-tel').value=n?.telIndicado||'';
  document.getElementById('ri-por').value=n?.indicadoPor||'';
  document.getElementById('btn-salvar-ind-txt').textContent=id?'Salvar Alterações':'Salvar';
  document.getElementById('ov-ind').classList.remove('hidden');setTimeout(()=>document.getElementById('ri-nome').focus(),50);
}
async function salvarIndicacao(){
  const nomeIndicado=document.getElementById('ri-nome').value.trim();
  if(!nomeIndicado){toast('Informe o nome indicado','red');return;}
  const btn=document.getElementById('btn-salvar-ind');btn.disabled=true;document.getElementById('btn-salvar-ind-txt').innerHTML='<span class="spin"></span>';
  const data={nomeIndicado,telIndicado:document.getElementById('ri-tel').value.trim(),indicadoPor:document.getElementById('ri-por').value.trim()};
  try{
    if(G.rel.editandoIndId){Object.assign(G.rel.indicacoes.find(x=>x.id===G.rel.editandoIndId),data);if(!G.rel.modoDemo)await fbUpdate('indicacoes_rel',G.rel.editandoIndId,data);toast('Indicação atualizada!');}
    else{const id=await proximoId('IND',G.rel.indicacoes,'rel_config/seq','indSeq');const n={id,tag:'',dt:new Date().toISOString().split('T')[0],by:G.user?.n||'',...data};G.rel.indicacoes.push(n);if(!G.rel.modoDemo)await fbCreate('indicacoes_rel',id,n);toast(`${nomeIndicado} adicionado!`);}
    fecharModal('ov-ind');renderRelacionamento();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
  finally{btn.disabled=false;document.getElementById('btn-salvar-ind-txt').textContent=G.rel.editandoIndId?'Salvar Alterações':'Salvar';}
}
async function setTagIndicacao(id,valor,e){
  e.stopPropagation();
  const n=G.rel.indicacoes.find(x=>x.id===id);if(!n)return;
  n.tag=n.tag===valor?'':valor;
  if(!G.rel.modoDemo)await fbUpdate('indicacoes_rel',id,{tag:n.tag});
  renderRelacionamento();
}
async function excluirIndicacao(id){
  if(!confirm('Excluir esta indicação?'))return;
  G.rel.indicacoes=G.rel.indicacoes.filter(x=>x.id!==id);
  try{if(!G.rel.modoDemo)await db.collection('indicacoes_rel').doc(id).delete();}catch(e){console.error(e);}
  toast('Indicação removida');renderRelacionamento();
}
function abrirModalInt(id){G.rel.detailId=id;const c=G.rel.clientes.find(x=>x.id===id);document.getElementById('int-titulo').textContent=`Registrar — ${c?.clienteNome||id}`;document.getElementById('int-tipo').value='📞 Ligação realizada';document.getElementById('int-obs').value='';document.getElementById('ov-int').classList.remove('hidden');setTimeout(()=>document.getElementById('int-obs').focus(),50);}
async function salvarInteracao(){
  const id=G.rel.detailId,c=G.rel.clientes.find(x=>x.id===id);if(!c)return;
  const tipo=document.getElementById('int-tipo').value,obs=document.getElementById('int-obs').value.trim();
  if(!obs){toast('Descreva a interação','red');return;}
  await regHistRel(c,tipo,obs,G.user?.n||'',tipo.split(' ')[0]);
  fecharModal('ov-int');toast('Registrado!');if(G.rel.detailId===id)abrirDetailCliente(id);renderRelacionamento();
}
function copiarMsg(id){
  const c=G.rel.clientes.find(x=>x.id===id);const col=c?colAtualRel(c):null;
  if(!col?.msg){toast('Etapa sem mensagem padrão','gold');return;}
  const msg=col.msg.replace(/\[NOME\]/g,c.clienteNome.split(' ')[0]).replace(/\[VEICULO\]/g,c.veiculo);
  navigator.clipboard.writeText(msg).then(()=>toast('Mensagem copiada! Cole no WhatsApp 💬')).catch(()=>prompt('Copie:',msg));
}
async function moverCliente(id,novaCol){
  const c=G.rel.clientes.find(x=>x.id===id);if(!c)return;
  await moverClienteParaCol(c,novaCol);abrirDetailCliente(id);renderRelacionamento();
}
async function regHistRel(c,acao,obs,by,emoji='📝'){if(!c.historico)c.historico=[];c.historico.push({dt:hoje(),emoji,acao,obs,by});await salvarCamposRel(c.id,{historico:c.historico});}
async function salvarCamposRel(id,campos){if(G.rel.modoDemo)return;try{await fbUpdate('clientes_rel',id,campos);}catch(e){console.error(e);toast('Erro ao salvar','red');}}

function abrirDetailCliente(id){
  G.rel.detailId=id;const c=G.rel.clientes.find(x=>x.id===id);if(!c)return;
  const col=colAtualRel(c);const dias=diasDesdeCompra(c.dtCompra);const aniv=aniversarioMes(c.dtNascimento);
  document.getElementById('detail-ov').classList.remove('hidden');
  const pnl=document.getElementById('detail-pnl');pnl.classList.remove('hidden');
  const hist=(c.historico||[]).slice().reverse();
  const histHtml=hist.length?hist.map(h=>`<div class="hist-item"><div class="hist-dot" style="background:${col.bg};font-size:16px">${h.emoji||'📝'}</div><div class="hist-info"><div class="hist-acao">${h.acao}</div>${h.obs?`<div class="hist-obs">${h.obs}</div>`:''}<div class="hist-meta">${h.dt} · ${h.by||'Sistema'}</div></div></div>`).join(''):'<div style="color:var(--tx3);font-size:12px">Nenhuma interação.</div>';
  const movBtns=COLS_REL.filter(x=>x.id!==col.id).map(x=>`<button class="col-btn" onclick="moverCliente('${id}','${x.id}')" style="border-color:${x.cor};color:${x.cor}">${x.emoji} ${x.label}</button>`).join('');
  pnl.innerHTML=`
    <div class="detail-head">
      <span style="font-size:22px">${col.emoji}</span>
      <h3>${c.clienteNome||'—'}</h3>
      <button class="mod-close" onclick="fecharDetail()"><i class="ti ti-x"></i></button>
    </div>
    <div class="detail-body">
      ${col.msg?`<div class="milestone-box"><span class="m-emoji">${col.emoji}</span><div class="m-title">${col.label} — ${col.acolabel}</div><div class="m-desc">${col.acao}</div><button class="btn btn-outline btn-sm" style="margin-top:10px" onclick="copiarMsg('${id}')"><i class="ti ti-copy"></i> Copiar mensagem WhatsApp</button></div>`:''}
      ${aniv?`<div style="background:var(--redl);border:1px solid var(--red);border-radius:var(--r);padding:10px 12px;margin-bottom:16px;font-size:12px;color:var(--red);font-weight:600">🎂 Aniversário este mês!</div>`:''}
      <div class="d-section"><div class="d-section-title">Cliente</div>
        <div class="d-grid">
          <div class="d-field" style="grid-column:1/-1"><span class="lbl">Nome</span><span class="val">${c.clienteNome}</span></div>
          <div class="d-field"><span class="lbl">Telefone</span><span class="val">${c.clienteTel||'—'}</span></div>
          <div class="d-field"><span class="lbl">E-mail</span><span class="val${!c.clienteEmail?' empty':''}">${c.clienteEmail||'—'}</span></div>
          <div class="d-field"><span class="lbl">Nascimento</span><span class="val">${isoParaBR(c.dtNascimento)||'—'}</span></div>
          <div class="d-field"><span class="lbl">Responsável</span><span class="val">${c.responsavel||c.by||'—'}</span></div>
          <div class="d-field"><span class="lbl">Vendedor (quem atendeu)</span><span class="val${!c.vendedor?' empty':''}">${c.vendedor||'—'}</span></div>
        </div>
      </div>
      <div class="d-section"><div class="d-section-title">Veículo</div>
        <div class="d-grid">
          <div class="d-field" style="grid-column:1/-1"><span class="lbl">Veículo</span><span class="val">${c.veiculo||'—'}</span></div>
          <div class="d-field"><span class="lbl">Data da compra</span><span class="val">${isoParaBR(c.dtCompra)||'—'}</span></div>
          <div class="d-field"><span class="lbl">Tempo de cliente</span><span class="val" style="color:${col.cor};font-weight:700">${labelDias(dias)} (${dias} dias)</span></div>
          ${c.valor?`<div class="d-field"><span class="lbl">Valor</span><span class="val">${c.valor}</span></div>`:''}
        </div>
        ${c.obs?`<div style="background:var(--bg3);border-radius:var(--r);padding:10px 12px;font-size:12px;color:var(--tx2);line-height:1.6;margin-top:8px">${c.obs}</div>`:''}
      </div>
      ${col.id!=='perdido'?`<div class="d-section"><div class="d-section-title">Indicação e Feedback</div>${toggleSimNaoRel(c,camposIndicFeedbackRel(col).ind,'Indicação','🤝')}${toggleSimNaoRel(c,camposIndicFeedbackRel(col).fb,'Feedback','💬')}${toggleSimNaoRel(c,'recompra','Recompra','🔁')}</div>`:''}
      <div class="d-section"><div class="d-section-title">Mover na jornada</div><div class="col-select">${movBtns}</div></div>
      <div class="d-section"><div class="d-section-title">Histórico (${hist.length})</div>${histHtml}</div>
    </div>
    <div class="detail-foot">
      <button class="btn btn-outline btn-sm" onclick="abrirModalCliente('${id}')"><i class="ti ti-pencil"></i> Editar</button>
      <button class="btn btn-red btn-sm" onclick="abrirModalInt('${id}')"><i class="ti ti-message-circle"></i> Registrar</button>
      ${col.msg?`<button class="btn btn-green btn-sm" onclick="copiarMsg('${id}')"><i class="ti ti-copy"></i> WhatsApp</button>`:''}
    </div>`;
}

/* KEYBOARD */
function handleKeydownRTCarCRM(e){
  if(e.key==='Escape'){['ov-lead','ov-obs','ov-vendido','ov-perda','ov-cliente','ov-nps','ov-ind','ov-int','ov-evento','ov-convidado','ov-obs-ws'].forEach(id=>fecharModal(id));fecharDetail();}
  if(e.key==='n'&&!e.ctrlKey&&!e.metaKey&&document.activeElement.tagName==='BODY'){G.modulo==='marketing'?abrirModalLead():abrirModalCliente();}
}


/* ============================================================
   WORKSHOP — MÓDULO
   ============================================================ */
async function initWorkshop(){
  // Reset state
  G.ws.eventoAtualId=null;
  G.ws.view='eventos';
  // Imediatamente limpa e mostra workshop — antes de qualquer await
  const cnt=document.getElementById('cnt');
  cnt.style.cssText='flex:1;overflow:hidden;display:flex;flex-direction:column';
  cnt.innerHTML='<div style="padding:40px;text-align:center;color:var(--tx3);flex:1"><i class="ti ti-loader-2"></i> Carregando Workshop...</div>';
  const tb=document.getElementById('tb');
  tb.innerHTML=`<div class="tb-title"><i class="ti ti-calendar-event" style="color:var(--purple)"></i> Workshop</div><div class="tb-sep"></div><div class="tb-tabs"><div class="tb-tab on">Eventos</div><div class="tb-tab">Dashboard</div></div>`;
  if(!fbOk()){initDemoWorkshop();return;}
  try{
    G.ws.eventos=await fbList('eventos_ws');
    G.ws.convidados=await fbList('convidados_ws');
  }catch(e){
    console.error('Workshop Firebase error:',e);
    G.ws.modoDemo=true;
    initDemoWorkshop();
    return;
  }
  if(G.modulo==='workshop') renderWorkshop();
}

function initDemoWorkshop(){
  G.ws.modoDemo=true;
  G.ws.eventos=[{id:'EV-001',nome:'Workshop RT Car — Agosto',data:'2026-08-10',hora:'10:00',valor:'Gratuito',obs:'Evento presencial na loja',dt:'10/08/2026'}];
  G.ws.convidados=[
    {id:'CV-001',eventoId:'EV-001',nome:'João Silva',whatsapp:'(47) 99999-1111',st:'confirmado',obs:'Interessado no Civic'},
    {id:'CV-002',eventoId:'EV-001',nome:'Maria Santos',whatsapp:'(47) 99999-2222',st:'convidado',obs:''},
    {id:'CV-003',eventoId:'EV-001',nome:'Carlos Rocha',whatsapp:'(47) 99999-3333',st:'presente',obs:''},
  ];
  renderWorkshop();
}

function renderWorkshop(){
  if(G.modulo!=='workshop')return;
  const cnt=document.getElementById('cnt');
  cnt.style.cssText='flex:1;overflow:hidden;display:flex;flex-direction:column';
  const tb=document.getElementById('tb');
  tb.innerHTML=`<div class="tb-title"><i class="ti ti-calendar-event" style="color:var(--purple)"></i> Workshop</div>
    <div class="tb-sep"></div>
    <div class="tb-tabs">
      <div class="tb-tab${G.ws.view==='eventos'?' on':''}" onclick="__G().ws.view='eventos';__G().ws.eventoAtualId=null;renderWorkshop()"><i class="ti ti-calendar-event"></i> Eventos</div>
      <div class="tb-tab${G.ws.view==='dashboard'?' on':''}" onclick="__G().ws.view='dashboard';__G().ws.eventoAtualId=null;renderWorkshop()"><i class="ti ti-chart-bar"></i> Dashboard</div>
    </div>
    <div class="tb-sep"></div>
    ${isManager()&&G.ws.view==='eventos'&&!G.ws.eventoAtualId?`<button class="btn btn-red btn-sm" onclick="abrirModalEvento()"><i class="ti ti-plus"></i> Novo Evento</button>`:''}
    ${isManager()&&G.ws.eventoAtualId?`<button class="btn btn-red btn-sm" onclick="abrirModalConvidado()"><i class="ti ti-user-plus"></i> Novo Convidado</button>`:''}`;
  if(G.ws.eventoAtualId){
    renderWsKanban(cnt);
  } else if(G.ws.view==='dashboard'){
    renderWsDashboard(cnt);
  } else {
    renderWsEventos(cnt);
  }
}

function renderWsEventos(cnt){
  const evs=G.ws.eventos;
  cnt.innerHTML='';
  // Header toolbar
  const hd=document.createElement('div');
  hd.style.cssText='padding:16px 20px;background:var(--bg2);border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between';
  hd.innerHTML=`<div style="font-size:15px;font-weight:700">📅 Eventos</div>${isManager()?`<button class="btn btn-red btn-sm" onclick="abrirModalEvento()"><i class="ti ti-plus"></i> Novo Evento</button>`:''}`;
  cnt.appendChild(hd);
  const grid=document.createElement('div');
  grid.className='ws-eventos';
  if(!evs.length){
    grid.innerHTML='<div style="color:var(--tx3);font-size:13px;padding:20px">Nenhum evento cadastrado ainda.</div>';
  } else {
    evs.forEach(ev=>{
      const convs=G.ws.convidados.filter(c=>c.eventoId===ev.id);
      const total=convs.length;
      const confirmados=convs.filter(c=>['confirmado','presente'].includes(c.st)).length;
      const presentes=convs.filter(c=>c.st==='presente').length;
      const taxa=total?Math.round(presentes/total*100):0;
      const card=document.createElement('div');
      card.className='ws-evento-card';
      card.innerHTML=`
        <div class="ws-ev-nome">${ev.nome}</div>
        <div class="ws-ev-meta">
          <span><i class="ti ti-calendar"></i> ${isoParaBR(ev.data)||ev.data||'—'} às ${ev.hora||'—'}</span>
          <span><i class="ti ti-ticket"></i> ${ev.valor||'Gratuito'}</span>
          ${ev.obs?`<span style="color:var(--tx2)">${ev.obs}</span>`:''}
        </div>
        <div class="ws-ev-stats">
          <span class="ws-stat">👥 ${total} convidados</span>
          <span class="ws-stat">✅ ${confirmados} confirm.</span>
          <span class="ws-stat">🏆 ${presentes} presentes</span>
          ${total?`<span class="ws-stat" style="background:var(--purplel);color:var(--purple)">${taxa}% comparec.</span>`:''}
        </div>`;
      card.onclick=()=>{G.ws.eventoAtualId=ev.id;renderWorkshop();};
      grid.appendChild(card);
    });
  }
  cnt.appendChild(grid);
}

function renderWsKanban(cnt){
  const ev=G.ws.eventos.find(e=>e.id===G.ws.eventoAtualId);
  if(!ev){G.ws.eventoAtualId=null;renderWorkshop();return;}
  const convs=G.ws.convidados.filter(c=>c.eventoId===ev.id);
  const total=convs.length;
  const confirmados=convs.filter(c=>['confirmado','presente'].includes(c.st)).length;
  const presentes=convs.filter(c=>c.st==='presente').length;
  const taxa=total?Math.round(presentes/total*100):0;
  cnt.innerHTML='';

  // Back + event header
  const hd=document.createElement('div');
  hd.style.cssText='padding:10px 20px;background:var(--bg2);border-bottom:1px solid var(--bdr);display:flex;align-items:center;gap:12px;flex-wrap:wrap';
  hd.innerHTML=`<span class="ws-back" onclick="__G().ws.eventoAtualId=null;renderWorkshop()"><i class="ti ti-arrow-left"></i> Eventos</span>
    <span style="color:var(--bdr)">|</span>
    <span style="font-weight:700;font-size:14px">${ev.nome}</span>
    <span style="font-size:11px;color:var(--tx3)">${isoParaBR(ev.data)||''} ${ev.hora?'às '+ev.hora:''}</span>
    <div style="margin-left:auto"><button class="btn btn-red btn-sm" onclick="abrirModalConvidado()"><i class="ti ti-user-plus"></i> Novo Convidado</button></div>`;
  cnt.appendChild(hd);

  // Metrics
  const met=document.createElement('div');
  met.className='ws-metrics';
  met.innerHTML=`
    <div class="ws-metric"><div class="ws-metric-val">${total}</div><div class="ws-metric-lbl">Convidados</div></div>
    <div class="ws-metric"><div class="ws-metric-val">${confirmados}</div><div class="ws-metric-lbl">Confirmados</div></div>
    <div class="ws-metric"><div class="ws-metric-val">${presentes}</div><div class="ws-metric-lbl">Presentes</div></div>
    <div class="ws-metric" style="background:var(--purplel)"><div class="ws-metric-val" style="color:var(--purple)">${taxa}%</div><div class="ws-metric-lbl">Compareceu</div></div>`;
  cnt.appendChild(met);

  // Kanban
  const kb=document.createElement('div');
  kb.className='ws-kb';
  COLS_WS.forEach(col=>{
    const cards=convs.filter(c=>c.st===col.id);
    const colEl=document.createElement('div');
    colEl.className='ws-col';
    colEl.addEventListener('dragover',e=>e.preventDefault());
    colEl.addEventListener('drop',()=>dropConvidado(col.id));
    // header
    const colHd=document.createElement('div');
    colHd.className='ws-col-hd';
    colHd.innerHTML=`<span class="ws-col-title" style="color:${col.cor}">${col.emoji} ${col.label}</span><span class="ws-col-cnt">${cards.length}</span>`;
    colEl.appendChild(colHd);
    // body — direct reference, no setTimeout
    const body=document.createElement('div');
    body.className='ws-col-body';
    cards.forEach(c=>{
      const card=document.createElement('div');
      card.className='ws-card';
      card.style.borderLeftColor=col.cor;
      card.draggable=true;
      card.addEventListener('dragstart',()=>{G.ws.dragId=c.id;card.classList.add('dragging')});
      card.addEventListener('dragend',()=>{G.ws.dragId=null;card.classList.remove('dragging')});
      const wha=c.whatsapp||'';
      card.innerHTML=`
        <div class="ws-card-nome">${c.nome||'(sem nome)'}</div>
        <div class="ws-card-tel"><i class="ti ti-brand-whatsapp" style="color:#25D366;font-size:12px"></i> ${wha||'—'}</div>
        ${c.obs?`<div class="ws-card-obs">${c.obs}</div>`:''}
        <div class="ws-card-actions">
          <button class="card-btn card-btn-label" onclick="event.stopPropagation();abrirModalObsWs('${c.id}')"><i class="ti ti-message-circle"></i> Obs</button>
          ${isManager()?`<button class="card-btn card-btn-label" onclick="event.stopPropagation();editarConvidado('${c.id}')"><i class="ti ti-edit"></i> Editar</button>`:''}
        </div>`;
      if(wha){
        const copyBtn=card.querySelector('.ws-card-tel');
        copyBtn.innerHTML+=`<button class="card-btn" style="width:18px;height:18px;margin-left:4px" onclick="event.stopPropagation();navigator.clipboard.writeText('${wha}');toast('Copiado!')"><i class="ti ti-copy" style="font-size:10px"></i></button>`;
      }
      body.appendChild(card);
    });
    const addBtn=document.createElement('div');
    addBtn.className='ws-add';
    addBtn.innerHTML='<i class="ti ti-plus"></i> Adicionar';
    addBtn.onclick=()=>abrirModalConvidado(col.id);
    body.appendChild(addBtn);
    colEl.appendChild(body);
    kb.appendChild(colEl);
  });
  cnt.appendChild(kb);
}

async function dropConvidado(novaCol){
  if(!G.ws.dragId)return;
  const conv=G.ws.convidados.find(c=>c.id===G.ws.dragId);
  if(!conv||conv.st===novaCol)return;
  conv.st=novaCol;
  if(!G.ws.modoDemo)await fbUpdate('convidados_ws',conv.id,{st:novaCol});
  renderWorkshop();
  const col=COLS_WS.find(c=>c.id===novaCol);
  toast(`${conv.nome} → ${col?.emoji} ${col?.label}`);
}

/* ---- MODAL EVENTO ---- */
function abrirModalEvento(){
  document.getElementById('ov-evento').classList.remove('hidden');
  ['wev-nome','wev-data','wev-hora','wev-valor','wev-obs'].forEach(id=>document.getElementById(id).value='');
}
async function salvarEvento(){
  const nome=document.getElementById('wev-nome').value.trim();
  if(!nome){alert('Informe o nome do evento');return;}
  const data={nome,data:document.getElementById('wev-data').value,hora:document.getElementById('wev-hora').value,valor:document.getElementById('wev-valor').value.trim(),obs:document.getElementById('wev-obs').value.trim(),dt:hoje(),criadoPor:G.user?.n||''};
  if(!G.ws.modoDemo){
    const id=await gerarId('eventos_ws','ws_config','ws_seq','EV');
    data.id=id;await fbCreate('eventos_ws',id,data);G.ws.eventos.push({...data});
  } else {data.id='EV-'+(G.ws.eventos.length+1).toString().padStart(3,'0');G.ws.eventos.push(data);}
  fecharModal('ov-evento');toast('Evento criado!');renderWorkshop();
}

/* ---- MODAL CONVIDADO ---- */
function abrirModalConvidado(stInicial){
  document.getElementById('ov-convidado').classList.remove('hidden');
  document.getElementById('wcv-id').value='';
  document.getElementById('wcv-nome').value='';
  document.getElementById('wcv-whatsapp').value='';
  document.getElementById('wcv-obs').value='';
  document.getElementById('wcv-st').value=stInicial||'convidado';
}
function editarConvidado(id){
  const c=G.ws.convidados.find(x=>x.id===id);if(!c)return;
  document.getElementById('ov-convidado').classList.remove('hidden');
  document.getElementById('wcv-id').value=c.id;
  document.getElementById('wcv-nome').value=c.nome||'';
  document.getElementById('wcv-whatsapp').value=c.whatsapp||'';
  document.getElementById('wcv-obs').value=c.obs||'';
  document.getElementById('wcv-st').value=c.st||'convidado';
}
async function salvarConvidado(){
  const nome=document.getElementById('wcv-nome').value.trim();
  if(!nome){alert('Informe o nome');return;}
  const editId=document.getElementById('wcv-id').value;
  const data={nome,whatsapp:document.getElementById('wcv-whatsapp').value.trim(),obs:document.getElementById('wcv-obs').value.trim(),st:document.getElementById('wcv-st').value||'convidado',eventoId:G.ws.eventoAtualId};
  if(editId){
    Object.assign(G.ws.convidados.find(c=>c.id===editId),data);
    if(!G.ws.modoDemo)await fbUpdate('convidados_ws',editId,data);
    toast('Convidado atualizado!');
  } else {
    if(!G.ws.modoDemo){
      const id=await gerarId('convidados_ws','ws_config','wcv_seq','CV');
      data.id=id;await fbCreate('convidados_ws',id,data);G.ws.convidados.push({...data});
    } else {data.id='CV-'+(G.ws.convidados.length+1).toString().padStart(3,'0');G.ws.convidados.push(data);}
    toast('Convidado adicionado!');
  }
  fecharModal('ov-convidado');renderWorkshop();
}

/* ---- MODAL OBS CONVIDADO ---- */
function abrirModalObsWs(id){
  document.getElementById('ov-obs-ws').classList.remove('hidden');
  document.getElementById('wobs-id').value=id;
  const c=G.ws.convidados.find(x=>x.id===id);
  document.getElementById('wobs-nome').textContent=c?.nome||'';
  document.getElementById('wobs-texto').value=c?.obs||'';
}
async function salvarObsWs(){
  const id=document.getElementById('wobs-id').value;
  const texto=document.getElementById('wobs-texto').value.trim();
  if(!texto)return;
  const c=G.ws.convidados.find(x=>x.id===id);if(!c)return;
  c.obs=texto;
  if(!G.ws.modoDemo)await fbUpdate('convidados_ws',id,{obs:texto});
  fecharModal('ov-obs-ws');toast('Observação salva!');renderWorkshop();
}

/* ---- WORKSHOP DASHBOARD ---- */
function renderWsDashboard(cnt){
  cnt.innerHTML='';
  const evs=G.ws.eventos;
  const convs=G.ws.convidados;
  const totalEvs=evs.length;
  const totalConvs=convs.length;
  const totalPresentes=convs.filter(c=>c.st==='presente').length;
  const totalConfirmados=convs.filter(c=>['confirmado','presente'].includes(c.st)).length;
  const taxaGeral=totalConvs?Math.round(totalPresentes/totalConvs*100):0;

  const wrap=document.createElement('div');
  wrap.style.cssText='padding:20px;overflow-y:auto;flex:1';

  // KPIs
  const kpis=document.createElement('div');
  kpis.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:24px';
  [
    {label:'Total de Eventos',val:totalEvs,icon:'ti-calendar-event',cor:'var(--purple)',bg:'var(--purplel)'},
    {label:'Total Convidados',val:totalConvs,icon:'ti-users',cor:'var(--blue)',bg:'var(--bluel)'},
    {label:'Confirmados',val:totalConfirmados,icon:'ti-circle-check',cor:'var(--green)',bg:'var(--greenl)'},
    {label:'Presentes',val:totalPresentes,icon:'ti-trophy',cor:'var(--gold)',bg:'var(--goldl)'},
    {label:'Taxa Geral',val:taxaGeral+'%',icon:'ti-chart-pie',cor:'var(--purple)',bg:'var(--purplel)'},
  ].forEach(k=>{
    kpis.innerHTML+=`<div style="background:${k.bg};border-radius:var(--r2);padding:16px 18px;border:1px solid var(--bdr)">
      <div style="font-size:24px;font-weight:700;color:${k.cor}">${k.val}</div>
      <div style="font-size:11px;color:var(--tx3);text-transform:uppercase;letter-spacing:.5px;margin-top:4px"><i class="ti ${k.icon}"></i> ${k.label}</div>
    </div>`;
  });
  wrap.appendChild(kpis);

  // Por evento
  if(evs.length){
    const tbl=document.createElement('div');
    tbl.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--tx2);margin-bottom:12px;text-transform:uppercase;letter-spacing:.5px">📊 Métricas por Evento</div>';
    evs.forEach(ev=>{
      const ec=convs.filter(c=>c.eventoId===ev.id);
      const ep=ec.filter(c=>c.st==='presente').length;
      const ec2=ec.filter(c=>['confirmado','presente'].includes(c.st)).length;
      const taxa=ec.length?Math.round(ep/ec.length*100):0;
      tbl.innerHTML+=`<div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px 18px;margin-bottom:10px;display:flex;align-items:center;gap:16px;flex-wrap:wrap">
        <div style="flex:1;min-width:160px">
          <div style="font-weight:700;font-size:13px">${ev.nome}</div>
          <div style="font-size:11px;color:var(--tx3)">${isoParaBR(ev.data)||'—'} ${ev.hora?'às '+ev.hora:''}</div>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <span class="ws-stat">👥 ${ec.length}</span>
          <span class="ws-stat">✅ ${ec2} confirm.</span>
          <span class="ws-stat">🏆 ${ep} presentes</span>
          <span class="ws-stat" style="background:var(--purplel);color:var(--purple)">${taxa}%</span>
        </div>
      </div>`;
    });
    wrap.appendChild(tbl);
  }
  cnt.appendChild(wrap);
}

/* ---- VISITAS DASHBOARD (no módulo Marketing) ---- */
function renderVisitasDashboard(cnt,filtroIni,filtroFim){
  cnt.innerHTML='';
  const origemVisita=['Passante','Loja','Evento Externo'];
  let leads=G.mk.leads.filter(l=>origemVisita.includes(l.origem));
  if(filtroIni){const d=new Date(filtroIni+'T00:00:00');leads=leads.filter(l=>l.dtISO&&new Date(l.dtISO+'T00:00:00')>=d);}
  if(filtroFim){const d=new Date(filtroFim+'T23:59:59');leads=leads.filter(l=>l.dtISO&&new Date(l.dtISO+'T00:00:00')<=d);}

  const total=leads.length;
  const vendidos=leads.filter(l=>l.st==='vendido').length;
  const taxa=total?Math.round(vendidos/total*100):0;

  // Group by date
  const porDia={};
  leads.forEach(l=>{const d=l.dtISO||'sem data';porDia[d]=(porDia[d]||0)+1;});
  const dias=Object.entries(porDia).sort((a,b)=>b[0].localeCompare(a[0]));

  // Group by origin
  const porOrigem={};
  leads.forEach(l=>{porOrigem[l.origem]=(porOrigem[l.origem]||0)+1;});

  const wrap=document.createElement('div');
  wrap.style.cssText='padding:20px;overflow-y:auto;flex:1';

  // Filter bar
  wrap.innerHTML=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:20px;flex-wrap:wrap">
    <span style="font-size:13px;font-weight:700;color:var(--tx2)">Período:</span>
    <input type="date" class="select-sm" id="vis-ini" value="${filtroIni||''}" style="width:130px">
    <input type="date" class="select-sm" id="vis-fim" value="${filtroFim||''}" style="width:130px">
    <button class="btn btn-red btn-sm" onclick="renderVisitasDashboard(document.getElementById('cnt'),document.getElementById('vis-ini').value,document.getElementById('vis-fim').value)"><i class="ti ti-search"></i> Filtrar</button>
    ${(filtroIni||filtroFim)?`<button class="btn btn-outline btn-sm" onclick="renderVisitasDashboard(document.getElementById('cnt'),'','')"><i class="ti ti-x"></i></button>`:''}
  </div>`;

  // KPIs
  const kpis=document.createElement('div');
  kpis.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;margin-bottom:24px';
  [
    {label:'Total Visitas',val:total,cor:'var(--blue)',bg:'var(--bluel)'},
    {label:'Vendidos',val:vendidos,cor:'var(--green)',bg:'var(--greenl)'},
    {label:'Conversão',val:taxa+'%',cor:'var(--gold)',bg:'var(--goldl)'},
    {label:'Em aberto',val:leads.filter(l=>!['vendido','perdido'].includes(l.st)).length,cor:'var(--purple)',bg:'var(--purplel)'},
  ].forEach(k=>{
    kpis.innerHTML+=`<div style="background:${k.bg};border-radius:var(--r2);padding:14px 16px;border:1px solid var(--bdr)">
      <div style="font-size:24px;font-weight:700;color:${k.cor}">${k.val}</div>
      <div style="font-size:11px;color:var(--tx3);text-transform:uppercase;letter-spacing:.5px;margin-top:4px">${k.label}</div>
    </div>`;
  });
  wrap.appendChild(kpis);

  // Por origem
  if(Object.keys(porOrigem).length){
    const orig=document.createElement('div');
    orig.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--tx2);margin-bottom:10px;text-transform:uppercase;letter-spacing:.5px">Por origem</div>';
    Object.entries(porOrigem).sort((a,b)=>b[1]-a[1]).forEach(([o,n])=>{
      orig.innerHTML+=`<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--bg3)">
        <span style="flex:1;font-size:13px">${o}</span><strong>${n}</strong>
      </div>`;
    });
    orig.style.cssText='background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px 18px;margin-bottom:16px';
    wrap.appendChild(orig);
  }

  // Por dia
  if(dias.length){
    const diaEl=document.createElement('div');
    diaEl.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--tx2);margin-bottom:10px;text-transform:uppercase;letter-spacing:.5px">Por dia</div>';
    const maxVal=Math.max(...dias.map(d=>d[1]));
    dias.slice(0,30).forEach(([d,n])=>{
      const pct=Math.round(n/maxVal*100);
      diaEl.innerHTML+=`<div style="padding:6px 0;border-bottom:1px solid var(--bg3)">
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:3px"><span>${isoParaBR(d)||d}</span><strong>${n}</strong></div>
        <div style="height:5px;background:var(--bg3);border-radius:3px"><div style="height:100%;width:${pct}%;background:var(--blue);border-radius:3px"></div></div>
      </div>`;
    });
    diaEl.style.cssText='background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px 18px';
    wrap.appendChild(diaEl);
  }

  if(!total){wrap.innerHTML+='<div style="color:var(--tx3);font-size:13px;padding:20px 0">Nenhuma visita encontrada no período.</div>';}
  cnt.appendChild(wrap);
}


