function anFiltrados(){
  let ls=[...G.an.anuncios];
  if(G.an.busca){const b=G.an.busca.toLowerCase();ls=ls.filter(a=>(a.nome||'').toLowerCase().includes(b));}
  return ls;
}

function renderKanbanAn(cnt){
  const wrap=document.createElement('div');wrap.className='kanban-wrap';
  COLS_AN.forEach(col=>{
    const ads=anFiltrados().filter(a=>a.st===col.id);
    const div=document.createElement('div');div.className='kb-col';
    const head=document.createElement('div');head.className='kb-col-head';
    head.innerHTML='<span style="font-size:16px">'+col.emoji+'</span><span class="col-lbl" style="color:'+col.cor+'">'+col.label+'</span><span class="col-cnt" style="background:'+col.bg+';color:'+col.cor+'">'+ads.length+'</span>';
    const desc=document.createElement('div');desc.className='kb-col-desc';desc.style.borderBottomColor=col.cor;desc.textContent=col.desc;
    const body=document.createElement('div');body.className='kb-col-body';body.dataset.col=col.id;
    body.addEventListener('dragover',e=>{e.preventDefault();body.classList.add('drag-over')});
    body.addEventListener('dragleave',()=>body.classList.remove('drag-over'));
    body.addEventListener('drop',e=>{e.preventDefault();body.classList.remove('drag-over');dropAnuncio(col.id)});
    ads.forEach(a=>{
      const cpl=a.cpl||(a.mensagens>0?+(+a.valorUsado/+a.mensagens).toFixed(2):0);
      const taxa=a.mensagens>0?Math.round(+a.respondidas/+a.mensagens*100):0;
      const taxaCor=taxa>=50?'#1a6b3c':taxa>=30?'#b8860b':'#e8431e';
      const card=document.createElement('div');card.className='ccard';card.style.borderLeftColor=col.cor;card.draggable=true;card.dataset.id=a.id;
      card.addEventListener('dragstart',()=>{G.an.dragId=a.id;card.classList.add('dragging')});
      card.addEventListener('dragend',()=>{G.an.dragId=null;card.classList.remove('dragging')});
      card.onclick=e=>{if(!e.target.closest('.card-btn'))abrirModalAn(a.id)};
      const vUsado='R$ '+(+a.valorUsado).toLocaleString('pt-BR',{minimumFractionDigits:0});
      const vOrc='R$ '+(+a.orcamentoMensal).toLocaleString('pt-BR',{minimumFractionDigits:0});
      const cplStr='R$ '+cpl.toLocaleString('pt-BR',{minimumFractionDigits:2});
      const cacStr=a.cac?'R$ '+a.cac:'—';
      card.innerHTML=
        (a.sucesso?'<span style="position:absolute;top:8px;right:8px;font-size:13px">🏆</span>':'')+
        '<div class="card-id">'+a.id+'</div>'+
        '<div class="card-nome" style="font-size:13px;font-weight:600;line-height:1.3;margin-bottom:8px">'+a.nome+'</div>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-bottom:8px">'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">Mensagens</div><div style="font-weight:600;font-size:13px">'+a.mensagens+' <span style="font-size:10px;color:var(--tx3)">/ '+a.respondidas+' resp</span></div></div>'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">Taxa resp.</div><div style="font-weight:600;font-size:13px;color:'+taxaCor+'">'+taxa+'%</div></div>'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">Valor usado</div><div style="font-weight:600;font-size:12px">'+vUsado+'</div></div>'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">CPL</div><div style="font-weight:600;font-size:12px">'+cplStr+'</div></div>'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">CAC</div><div style="font-weight:600;font-size:12px">'+cacStr+'</div></div>'+
          '<div style="background:var(--bg3);border-radius:6px;padding:5px 8px;font-size:11px"><div style="color:var(--tx3)">Orc. mensal</div><div style="font-weight:600;font-size:12px">'+vOrc+'</div></div>'+
        '</div>'+
        '<div style="font-size:10px;color:var(--tx3);display:flex;gap:8px;margin-bottom:6px">'+
          '<span><i class="ti ti-calendar"></i> '+(a.inicio||'—')+'</span>'+
          (a.fim?'<span>→ '+a.fim+'</span>':'<span style="color:#1a6b3c">Em andamento</span>')+
        '</div>'+
        (a.obs?'<div style="font-size:10px;color:#b8860b;background:#faf6e8;border-radius:4px;padding:3px 6px;margin-bottom:6px">⚠️ '+a.obs+'</div>':'')+
        '<div class="card-footer">'+
          '<span style="font-size:10px;color:var(--tx3)">Sucesso: '+(a.sucesso||0)+'</span>'+
          '<div class="card-actions"><button class="card-btn card-btn-label" onclick="abrirModalAn(\''+a.id+'\')"><i class="ti ti-edit"></i> Editar</button></div>'+
        '</div>';
      body.appendChild(card);
    });
    const add=document.createElement('div');add.className='kb-add';add.innerHTML='<i class="ti ti-plus"></i> Novo Anuncio';add.onclick=()=>{abrirModalAn();setTimeout(()=>{const s=document.getElementById('an-st');if(s)s.value=col.id;},50);};
    div.appendChild(head);div.appendChild(desc);div.appendChild(body);div.appendChild(add);wrap.appendChild(div);
  });
  cnt.appendChild(wrap);
}

async function dropAnuncio(novaCol){
  if(!G.an.dragId)return;
  const a=G.an.anuncios.find(x=>x.id===G.an.dragId);if(!a||a.st===novaCol)return;
  a.st=novaCol;
  if(fbOk()) await salvarCamposAn(a.id,{st:novaCol});
  const col=COLS_AN.find(c=>c.id===novaCol);
  toast(a.nome+' → '+(col?col.label:novaCol));
  renderAnuncios();
}

function renderDashboardAn(cnt){
  cnt.style.cssText='flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:20px';
  const ads=G.an.anuncios;
  const ativos=ads.filter(a=>a.st==='ativo');
  const totalInvestido=ads.reduce((s,a)=>s+(+a.valorUsado||0),0);
  const totalMensagens=ads.reduce((s,a)=>s+(+a.mensagens||0),0);
  const totalRespondidas=ads.reduce((s,a)=>s+(+a.respondidas||0),0);
  const totalSucesso=ads.reduce((s,a)=>s+(+a.sucesso||0),0);
  const cplMedio=totalMensagens>0?+(totalInvestido/totalMensagens).toFixed(2):0;
  const taxaResp=totalMensagens>0?Math.round(totalRespondidas/totalMensagens*100):0;
  const taxaCor=taxaResp>=50?'#1a6b3c':taxaResp>=30?'#b8860b':'#e8431e';
  const orcAtivo=ativos.reduce((s,a)=>s+(+a.orcamentoMensal||0),0);
  const R=v=>'R$ '+(+v).toLocaleString('pt-BR',{minimumFractionDigits:0});
  const R2=v=>'R$ '+(+v).toLocaleString('pt-BR',{minimumFractionDigits:2});
  function kpi(val,label,cor,bg){
    return '<div style="background:'+(bg||'var(--bg2)')+';border:1px solid var(--bdr);border-radius:var(--r2);padding:14px;text-align:center">'+
      '<div style="font-size:22px;font-weight:700;color:'+cor+'">'+val+'</div>'+
      '<div style="font-size:11px;color:var(--tx3);margin-top:3px">'+label+'</div></div>';
  }
  const sorted=ads.slice().sort((a,b)=>{const o={ativo:0,ajuste:1,pausado:2,encerrado:3};return(o[a.st]||0)-(o[b.st]||0);});
  const rows=sorted.map(a=>{
    const col=COLS_AN.find(c=>c.id===a.st)||COLS_AN[0];
    const cpl=a.cpl||(a.mensagens>0?+(+a.valorUsado/+a.mensagens).toFixed(2):0);
    const taxa=a.mensagens>0?Math.round(+a.respondidas/+a.mensagens*100):0;
    const tc=taxa>=50?'#1a6b3c':taxa>=30?'#b8860b':'#e8431e';
    return '<tr style="border-bottom:1px solid var(--bdr)">'+
      '<td style="padding:8px;font-weight:500">'+a.nome+'</td>'+
      '<td style="padding:8px;text-align:center"><span style="background:'+col.bg+';color:'+col.cor+';padding:2px 8px;border-radius:20px;font-size:10px">'+col.emoji+' '+col.label+'</span></td>'+
      '<td style="padding:8px;text-align:right">'+a.mensagens+'</td>'+
      '<td style="padding:8px;text-align:right">'+a.respondidas+' <span style="color:'+tc+';font-size:10px">('+taxa+'%)</span></td>'+
      '<td style="padding:8px;text-align:right">'+R(a.valorUsado)+'</td>'+
      '<td style="padding:8px;text-align:right">'+R2(cpl)+'</td>'+
      '<td style="padding:8px;text-align:right">'+(a.cac?R(a.cac):'—')+'</td>'+
      '<td style="padding:8px;text-align:right">'+R(a.orcamentoMensal)+'</td>'+
      '<td style="padding:8px;text-align:center">'+(a.sucesso?'🏆 '+a.sucesso:'—')+'</td>'+
      '<td style="padding:8px;font-size:11px;color:var(--tx3)">'+(a.inicio||'—')+(a.fim?' → '+a.fim:' (ativo)')+'</td>'+
    '</tr>';
  }).join('');
  cnt.innerHTML=
    '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">'+
      kpi(ativos.length,'Anuncios ativos','#1a6b3c','#e8f5ee')+
      kpi(R(totalInvestido),'Total investido','var(--red)','')+
      kpi(R(orcAtivo),'Orc. mensal ativo','#1e4d8c','#e8f0fb')+
      kpi(totalMensagens,'Leads gerados','#6b3db8','#f3e8fb')+
      kpi(totalRespondidas,'Respondidos','#0b7ba8','#e8f8fb')+
      kpi(taxaResp+'%','Taxa de resposta',taxaCor,'')+
      kpi(R2(cplMedio),'CPL medio','#b8860b','#faf6e8')+
      kpi(totalSucesso,'Sucessos','#1a6b3c','#e8f5ee')+
    '</div>'+
    '<div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:16px;overflow-x:auto">'+
      '<div style="font-size:13px;font-weight:600;margin-bottom:12px">📊 Performance por Anuncio</div>'+
      '<table style="width:100%;border-collapse:collapse;font-size:12px">'+
        '<thead><tr style="border-bottom:2px solid var(--bdr)">'+
          '<th style="text-align:left;padding:6px 8px;color:var(--tx3)">Anuncio</th>'+
          '<th style="text-align:center;padding:6px 8px;color:var(--tx3)">Status</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">Mensagens</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">Respondidas</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">Valor usado</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">CPL</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">CAC</th>'+
          '<th style="text-align:right;padding:6px 8px;color:var(--tx3)">Orc. mensal</th>'+
          '<th style="text-align:center;padding:6px 8px;color:var(--tx3)">Sucesso</th>'+
          '<th style="text-align:left;padding:6px 8px;color:var(--tx3)">Periodo</th>'+
        '</tr></thead>'+
        '<tbody>'+rows+'</tbody>'+
      '</table>'+
    '</div>';
}

/* ---- CRUD ANUNCIOS ---- */
function abrirModalAn(id){
  const a=id?G.an.anuncios.find(x=>x.id===id):null;
  const titulo=a?'Editar Anuncio':'Novo Anuncio';
  const st=a?a.st:'ativo';
  const opts=COLS_AN.map(c=>'<option value="'+c.id+'"'+(st===c.id?' selected':'')+'>'+c.emoji+' '+c.label+'</option>').join('');
  document.getElementById('ov-an').classList.remove('hidden');
  document.getElementById('mod-an').innerHTML=
    '<div class="mod-head"><span>'+titulo+'</span><button class="mod-close" onclick="fecharModal(\'ov-an\')"><i class="ti ti-x"></i></button></div>'+
    '<div class="mod-body" style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+
      '<div style="grid-column:1/-1"><label class="lbl">Nome do Anuncio</label><input class="inp" id="an-nome" value="'+(a?a.nome:'')+'" placeholder="Ex: Nivus GTS 2026 Branco"></div>'+
      '<div><label class="lbl">Status</label><select class="inp" id="an-st">'+opts+'</select></div>'+
      '<div><label class="lbl">Sucesso (vendas)</label><input class="inp" id="an-sucesso" type="number" min="0" value="'+(a?a.sucesso:0)+'"></div>'+
      '<div><label class="lbl">Mensagens recebidas</label><input class="inp" id="an-mensagens" type="number" min="0" value="'+(a?a.mensagens:0)+'"></div>'+
      '<div><label class="lbl">Respondidas</label><input class="inp" id="an-respondidas" type="number" min="0" value="'+(a?a.respondidas:0)+'"></div>'+
      '<div><label class="lbl">Valor usado (R$)</label><input class="inp" id="an-valor" type="number" min="0" step="0.01" value="'+(a?a.valorUsado:0)+'"></div>'+
      '<div><label class="lbl">Orcamento mensal (R$)</label><input class="inp" id="an-orcamento" type="number" min="0" value="'+(a?a.orcamentoMensal:0)+'"></div>'+
      '<div><label class="lbl">CPL (opcional)</label><input class="inp" id="an-cpl" type="number" min="0" step="0.01" value="'+(a?a.cpl:0)+'" placeholder="Calculado automaticamente"></div>'+
      '<div><label class="lbl">CAC (R$)</label><input class="inp" id="an-cac" type="number" min="0" step="0.01" value="'+(a?a.cac:0)+'"></div>'+
      '<div><label class="lbl">Inicio</label><input class="inp" id="an-inicio" type="date" value="'+(a?a.inicio:'')+'"></div>'+
      '<div><label class="lbl">Fim</label><input class="inp" id="an-fim" type="date" value="'+(a?a.fim:'')+'"></div>'+
      '<div style="grid-column:1/-1"><label class="lbl">Observacao</label><input class="inp" id="an-obs" value="'+(a?a.obs:'')+'" placeholder="Ex: TROCAR VIDEO, ajustar orcamento..."></div>'+
    '</div>'+
    '<div class="mod-foot">'+
      (a?'<button class="btn btn-ghost btn-sm" onclick="excluirAn(\''+a.id+'\')"><i class="ti ti-trash"></i> Excluir</button>':'<span></span>')+
      '<button class="btn btn-red" onclick="salvarAn(\''+(a?a.id:'')+'\')" ><i class="ti ti-check"></i> Salvar</button>'+
    '</div>';
}

async function salvarAn(id){
  const nome=(document.getElementById('an-nome').value||'').trim();
  if(!nome){toast('Nome obrigatorio','red');return;}
  const dados={
    nome,
    st:document.getElementById('an-st').value,
    mensagens:+document.getElementById('an-mensagens').value||0,
    respondidas:+document.getElementById('an-respondidas').value||0,
    valorUsado:+document.getElementById('an-valor').value||0,
    orcamentoMensal:+document.getElementById('an-orcamento').value||0,
    cpl:+document.getElementById('an-cpl').value||0,
    cac:+document.getElementById('an-cac').value||0,
    sucesso:+document.getElementById('an-sucesso').value||0,
    inicio:document.getElementById('an-inicio').value,
    fim:document.getElementById('an-fim').value,
    obs:(document.getElementById('an-obs').value||'').trim(),
    by:G.user?G.user.n:'',uid:G.user?G.user.uid:''
  };
  try{
    if(id){
      const a=G.an.anuncios.find(x=>x.id===id);if(a)Object.assign(a,dados);
      if(fbOk()) await salvarCamposAn(id,dados);
      toast('Anuncio atualizado!');
    } else {
      const nid=gerarIdAn();
      const novo=Object.assign({id:nid},dados);
      G.an.anuncios.push(novo);
      if(fbOk()){await fbSet('anuncios',nid,novo);}
      toast('Anuncio '+nid+' criado!');
    }
    fecharModal('ov-an');renderAnuncios();
  }catch(e){console.error(e);toast('Erro ao salvar','red');}
}

async function excluirAn(id){
  if(!confirm('Excluir este anuncio?'))return;
  G.an.anuncios=G.an.anuncios.filter(x=>x.id!==id);
  if(fbOk()){try{await fbDel('anuncios',id);}catch(e){}}
  fecharModal('ov-an');toast('Anuncio removido');renderAnuncios();
}

async function salvarCamposAn(id,campos){
  if(!fbOk())return;
  await fbUpdate('anuncios',id,campos);
}


/* ============================================================
   IA (EVA) — MÓDULO
   ============================================================ */
function iaLeadsEva(){
  return G.ia.leads.filter(l=>l.eloaEnviadoEm||(l.conversaEloa&&l.conversaEloa.length));
}
function iaLeadsFiltrados(){
  let ls=iaLeadsEva();
  if(G.ia.filtroStatus==='ia')ls=ls.filter(l=>l.st==='ia');
  else if(G.ia.filtroStatus==='atendimento')ls=ls.filter(l=>l.st==='atendimento');
  if(G.ia.filtroVendedor)ls=ls.filter(l=>l.captador===G.ia.filtroVendedor);
  if(G.ia.busca){
    const b=G.ia.busca.toLowerCase();
    const bDigits=G.ia.busca.replace(/\D/g,'');
    ls=ls.filter(l=>(l.clienteNome||'').toLowerCase().includes(b)||(l.id||'').toLowerCase().includes(b)||(bDigits.length>0&&(l.clienteTel||'').replace(/\D/g,'').includes(bDigits)));
  }
  return ls.sort((a,b)=>(b.id||'').localeCompare(a.id||''));
}
async function initIA(){
  try{G.ia.leads=await fbList('leads');}catch(e){console.error(e);toast('Erro ao carregar dados da IA.','red');}
  renderIA(document.getElementById('cnt'));
  iniciarTimerIA();
}
function iniciarTimerIA(){
  if(G.ia._timerInterval)clearInterval(G.ia._timerInterval);
  G.ia._timerInterval=setInterval(async()=>{
    if(G.modulo!=='ia'){clearInterval(G.ia._timerInterval);G.ia._timerInterval=null;return;}
    if(document.activeElement&&document.activeElement.id==='ia-busca')return;
    try{G.ia.leads=await fbList('leads');renderIA(document.getElementById('cnt'));}catch(e){console.error(e);}
  },10000);
}
function pararTimerIA(){if(G.ia._timerInterval){clearInterval(G.ia._timerInterval);G.ia._timerInterval=null;}}
function iaBadgeStatus(st){
  if(st==='ia')return '<span class="badge" style="background:var(--bluel);color:var(--blue)">NA IA</span>';
  if(st==='atendimento')return '<span class="badge" style="background:var(--goldl);color:var(--gold)">TRANSFERIDO</span>';
  return `<span class="badge" style="background:var(--bg3);color:var(--tx3)">${st||'-'}</span>`;
}
function iaKpiCard(val,label,color,icone){
  return `<div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:14px;text-align:center">
    <div style="font-size:24px;font-weight:700;color:${color}"><i class="ti ${icone}" style="font-size:18px;margin-right:4px"></i>${val}</div>
    <div style="font-size:11px;color:var(--tx3);margin-top:3px">${label}</div>
  </div>`;
}
function renderIA(cnt){
  if(G.modulo!=='ia')return;
  const todos=iaLeadsEva();
  const total=todos.length;
  const naIA=todos.filter(l=>l.st==='ia').length;
  const transferidos=todos.filter(l=>l.st==='atendimento').length;
  const responderam=todos.filter(l=>(l.conversaEloa||[]).some(m=>m.role==='user')).length;
  const taxaResposta=total?Math.round(responderam/total*100):0;
  const followUpsAtivos=todos.filter(l=>(l.followUpStep||0)>0&&l.st==='ia').length;
  const porVendedor={};
  todos.forEach(l=>{const v=l.captador||'(sem vendedor)';porVendedor[v]=(porVendedor[v]||0)+1;});
  const vendedoresLista=Object.entries(porVendedor).sort((a,b)=>b[1]-a[1]);
  const filtrados=iaLeadsFiltrados();
  const leadSel=filtrados.find(l=>l.id===G.ia.detailId)||todos.find(l=>l.id===G.ia.detailId);
  const listaHtml=filtrados.length?filtrados.map(l=>{
    const conversa=l.conversaEloa||[];
    const ultima=conversa.length?conversa[conversa.length-1].texto:(l.obs||'');
    const ativo=l.id===G.ia.detailId;
    const step=l.followUpStep||0;
    return `<div onclick="__G().ia.detailId='${l.id}';renderIA(document.getElementById('cnt'))" style="padding:10px;border-radius:8px;margin-bottom:5px;cursor:pointer;background:${ativo?'var(--bluel)':'transparent'};border:1px solid ${ativo?'var(--blue)':'transparent'}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px">
        <span style="font-weight:600;font-size:12.5px">${l.clienteNome||l.id}</span>
        ${iaBadgeStatus(l.st)}
      </div>
      <div style="font-size:11px;color:var(--tx3)">${l.captador||'sem vendedor'} · ${l.origem||'-'}${step>0?` · follow-up ${step}/4`:''}</div>
      <div style="font-size:11px;color:var(--tx3);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${(ultima||'').replace(/</g,'&lt;')}</div>
    </div>`;
  }).join(''):'<div style="text-align:center;color:var(--tx3);padding:30px 10px;font-size:12px">Nenhum lead encontrado com esses filtros.</div>';
  let conversaHtml;
  if(!leadSel){
    conversaHtml=`<div style="flex:1;display:flex;align-items:center;justify-content:center;color:var(--tx3);font-size:13px">Selecione um lead à esquerda pra ver a conversa.</div>`;
  }else{
    const conversa=leadSel.conversaEloa||[];
    const bolhas=conversa.length?conversa.map(m=>{
      const isEva=m.role==='model';
      return `<div style="max-width:65%;align-self:${isEva?'flex-start':'flex-end'};background:${isEva?'var(--bg3)':'var(--bluel)'};padding:9px 13px;border-radius:12px;font-size:13px;line-height:1.45">
        <div style="font-size:9.5px;color:var(--tx3);font-weight:700;margin-bottom:2px;letter-spacing:.3px">${isEva?'EVA':(leadSel.clienteNome||'CLIENTE').toUpperCase()}</div>
        ${(m.texto||'').replace(/</g,'&lt;')}
      </div>`;
    }).join(''):'<div style="color:var(--tx3);font-size:12px;text-align:center;padding:20px">Ainda sem mensagens.</div>';
    const desde=leadSel.ultimaMensagemEm||leadSel.eloaEnviadoEm;
    conversaHtml=`
      <div style="padding:14px 18px;border-bottom:1px solid var(--bdr);display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-weight:700;font-size:14px">${leadSel.clienteNome||leadSel.id}</div>
          <div style="font-size:11px;color:var(--tx3);margin-top:2px">${leadSel.clienteTel||'-'} · ${leadSel.veiculo||'sem veículo'} · ${leadSel.id}${desde==='NUMERO_INVALIDO'?' · telefone inválido — não enviado':(desde?` · última mensagem há ${calcElapsed(desde,null)}`:'')}</div>
        </div>
        ${leadSel.captador?`<span class="badge" style="background:var(--purplel);color:var(--purple)">${leadSel.captador}</span>`:''}
      </div>
      <div style="flex:1;overflow-y:auto;padding:16px 18px;display:flex;flex-direction:column;gap:8px">${bolhas}</div>
    `;
  }
  cnt.innerHTML=`
    <div style="padding:20px;overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:16px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <div style="font-size:19px;font-weight:700">🤖 IA (Eva)</div>
          <div style="font-size:12px;color:var(--tx3)">Atendimento automático via WhatsApp — leads, conversas e follow-up em tempo real</div>
        </div>
        <button class="btn btn-outline btn-sm" onclick="initIA()"><i class="ti ti-refresh"></i> Atualizar</button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px">
        ${iaKpiCard(total,'Leads atendidos pela Eva','var(--tx)','ti-robot')}
        ${iaKpiCard(naIA,'Aguardando na IA','var(--blue)','ti-clock')}
        ${iaKpiCard(transferidos,'Transferidos p/ vendedor','var(--gold)','ti-arrow-right')}
        ${iaKpiCard(taxaResposta+'%','Taxa de resposta','var(--green)','ti-message-check')}
        ${iaKpiCard(followUpsAtivos,'Follow-ups em andamento','var(--purple)','ti-repeat')}
      </div>
      <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:var(--r2);padding:12px 14px">
        <div style="font-size:11px;font-weight:700;color:var(--tx2);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">Distribuição por vendedor</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          ${vendedoresLista.map(([v,n])=>`<span class="badge" style="background:var(--bg3);color:var(--tx2)">${v}: ${n}</span>`).join('')}
        </div>
      </div>
      <div style="display:flex;gap:14px;flex:1;min-height:420px">
        <div style="width:320px;flex-shrink:0;display:flex;flex-direction:column;border:1px solid var(--bdr);border-radius:var(--r2);background:var(--bg2);overflow:hidden">
          <div style="padding:10px;border-bottom:1px solid var(--bdr);display:flex;flex-direction:column;gap:7px">
            <input id="ia-busca" type="text" placeholder="Buscar por nome/telefone/ID..." value="${G.ia.busca}" oninput="__G().ia.busca=this.value;renderIA(document.getElementById('cnt'))" style="padding:8px 10px;border:1.5px solid var(--bdr);border-radius:8px;font-size:12px;font-family:var(--f)">
            <select onchange="__G().ia.filtroStatus=this.value;renderIA(document.getElementById('cnt'))" style="padding:7px;border:1.5px solid var(--bdr);border-radius:8px;font-size:12px;font-family:var(--f)">
              <option value="todos"${G.ia.filtroStatus==='todos'?' selected':''}>Todos os status</option>
              <option value="ia"${G.ia.filtroStatus==='ia'?' selected':''}>Na IA (aguardando)</option>
              <option value="atendimento"${G.ia.filtroStatus==='atendimento'?' selected':''}>Transferido</option>
            </select>
            <select onchange="__G().ia.filtroVendedor=this.value;renderIA(document.getElementById('cnt'))" style="padding:7px;border:1.5px solid var(--bdr);border-radius:8px;font-size:12px;font-family:var(--f)">
              <option value="">Todos os vendedores</option>
              ${VENDEDORES_ATIVOS.map(v=>`<option value="${v}"${G.ia.filtroVendedor===v?' selected':''}>${v}</option>`).join('')}
            </select>
          </div>
          <div style="flex:1;overflow-y:auto;padding:6px">${listaHtml}</div>
        </div>
        <div style="flex:1;border:1px solid var(--bdr);border-radius:var(--r2);background:var(--bg2);display:flex;flex-direction:column;overflow:hidden">
          ${conversaHtml}
        </div>
      </div>
    </div>
  `;
}


/* ============================================================
   API DE EMBUTIR NO SISTEMA PRINCIPAL (isolamento pedido pelo
   Claude da Marcela, 03/09/2026) - unica coisa exposta fora
   desta IIFE e' window.RTCarCRM = {montar, desmontar}.
   ============================================================ */
let _rtcarCrmMontado=false;
// Se o sistema principal ja tem alguem logado no MESMO Firebase Auth
// (os dois projetos compartilham conta), pula a tela de login propria do
// CRM e entra direto - sem pedir senha de novo. So funciona se o e-mail
// logado tambem estiver cadastrado em USUARIOS (perfil/permissao deste
// CRM); senao, mostra a tela de login normal (sem deslogar a sessao
// compartilhada - isso derrubaria a pessoa do sistema principal tambem).
function tentarAutoLogin(){
  const atual=fbAuth.currentUser;
  if(!atual||!atual.email)return false;
  const u=USUARIOS.find(x=>x.e.toLowerCase()===atual.email.toLowerCase());
  if(!u)return false;
  entrarNaApp(u);
  return true;
}
function montarRTCarCRM(containerEl){
  garantirRootDOM();
  const root=document.getElementById('rtcar-crm-root');
  if(!root||!containerEl)return;
  containerEl.appendChild(root);
  root.classList.remove('hidden');
  if(!_rtcarCrmMontado){
    document.addEventListener('keydown',handleKeydownRTCarCRM);
    _rtcarCrmMontado=true;
  }
  if(containerEl===document.body){
    // Modo standalone (arquivo aberto direto, dono da pagina inteira) -
    // sem isso, height:100% do root nao teria altura de referencia (o
    // reset de CSS do CRM esta todo escopado dentro de #rtcar-crm-root,
    // entao html/body do modo embutido nunca sao tocados por aqui).
    document.documentElement.style.height='100%';
    document.body.style.height='100%';
    document.body.style.margin='0';
  }
  tentarAutoLogin();
}
function desmontarRTCarCRM(){
  pararTimerCRM();
  pararAutoRefreshMk();
  pararTimerIA();
  document.removeEventListener('keydown',handleKeydownRTCarCRM);
  _rtcarCrmMontado=false;
  const root=document.getElementById('rtcar-crm-root');
  if(root){
    root.classList.add('hidden');
    document.body.appendChild(root);
  }
}

// Handlers inline (onclick="..." etc, no HTML estatico e nas strings de
// template que o JS gera) rodam no escopo GLOBAL do navegador, entao toda
// funcao referenciada assim precisa existir em window - mesmo estando
// isolada aqui dentro da IIFE. Gerado automaticamente (achando toda funcao
// chamada dentro de algum on*="..." que realmente existe no arquivo).
window.abrirDetailLead=abrirDetailLead;
window.abrirDrill=abrirDrill;
window.abrirDrillMk=abrirDrillMk;
window.abrirDrillMkPeriodo=abrirDrillMkPeriodo;
window.abrirModalAn=abrirModalAn;
window.abrirModalCliente=abrirModalCliente;
window.abrirModalConvidado=abrirModalConvidado;
window.abrirModalEvento=abrirModalEvento;
window.abrirModalInt=abrirModalInt;
window.abrirModalIntegracoes=abrirModalIntegracoes;
window.abrirModalLead=abrirModalLead;
window.abrirModalObs=abrirModalObs;
